insert into public.catalog_ancestries (id,name_pt,name_en,description_pt,size,speed_feet,languages,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cor.ancestry.cor-extaminaar','Extaminaar','Extaminaar','Low-Light Vision: can see twice as far as a human in starlight, moonlight, torchlight, and similar conditions of poor illumination; retains the ability to distinguish color and detail under these conditions. +2 racial bonus on Fortitude saves versus poison. +4 racial bonus on Swim checks. +2 racial bonus on Escape Artist checks. Spell-Like Abilities: at will—speak with animals (snakes only); 3/day—charm animal (snakes only).','Medium',30,ARRAY['Common','Turmic','Yuan-ti']::text[],ARRAY[]::text[],'v35-cor','D&D 3.5 — Champions of Ruin',12,'dnd35','{"id":"cor-extaminaar","name":"Extaminaar","abilityAdjustments":{"Str":-2,"Dex":2},"size":"Medium","speedFt":30,"levelAdjustment":0,"favoredClass":"Rogue","automaticLanguages":["Common","Turmic","Yuan-ti"],"bonusLanguages":["Abyssal","Chondathan","Draconic"],"traits":["Low-Light Vision: can see twice as far as a human in starlight, moonlight, torchlight, and similar conditions of poor illumination; retains the ability to distinguish color and detail under these conditions.","+2 racial bonus on Fortitude saves versus poison.","+4 racial bonus on Swim checks.","+2 racial bonus on Escape Artist checks.","Spell-Like Abilities: at will—speak with animals (snakes only); 3/day—charm animal (snakes only)."]}'::jsonb),
('dnd35.cor.ancestry.cor-krinth','Krinth','Krinth','Darkvision out to 60 feet. +1 racial bonus on all Will saves. +1 bonus on all saving throws against spells and spell-like abilities with the shadow descriptor. +2 racial bonus on Hide checks in shadowy conditions. +4 racial bonus on saving throws against fear. Krinth cannot become shaken, and they ignore the effects of the shaken condition; they can still become frightened or panicked.','Medium',30,ARRAY['Common','Netherese']::text[],ARRAY[]::text[],'v35-cor','D&D 3.5 — Champions of Ruin',12,'dnd35','{"id":"cor-krinth","name":"Krinth","abilityAdjustments":{"Con":2,"Cha":-2},"size":"Medium","speedFt":30,"levelAdjustment":0,"favoredClass":"Fighter","automaticLanguages":["Common","Netherese"],"bonusLanguages":["Abyssal","Chondathan","Damaran","Undercommon"],"traits":["Darkvision out to 60 feet.","+1 racial bonus on all Will saves.","+1 bonus on all saving throws against spells and spell-like abilities with the shadow descriptor.","+2 racial bonus on Hide checks in shadowy conditions.","+4 racial bonus on saving throws against fear.","Krinth cannot become shaken, and they ignore the effects of the shaken condition; they can still become frightened or panicked."]}'::jsonb),
('dnd35.cor.ancestry.cor-draegloth','Draegloth','Draegloth','+2 Constitution. Immune to sleep-inducing spells and effects. +2 racial bonus on saving throws against enchantment spells or effects. Level Adjustment +4: with its 6 Hit Dice, the draegloth has an ECL of 10.','Medium',30,ARRAY['Abyssal','Elven','Undercommon']::text[],ARRAY['monster-class']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',10,'dnd35','{"id":"cor-draegloth","name":"Draegloth","levelAdjustment":4,"baseSpeedFt":30,"darkvisionFt":60,"favoredClass":"Cleric","automaticLanguages":["Abyssal","Elven","Undercommon"],"bonusLanguages":["Aquan","Common","Draconic","Drow Sign Language","Gnome","Goblin","Kuo-toan"],"racialTraits":["+2 Constitution.","Immune to sleep-inducing spells and effects.","+2 racial bonus on saving throws against enchantment spells or effects.","Level Adjustment +4: with its 6 Hit Dice, the draegloth has an ECL of 10."],"classSkills":["Climb","Concentration","Craft","Hide","Jump","Knowledge (arcana)","Knowledge (the planes)","Knowledge (religion)","Listen","Move Silently","Search","Spellcraft","Spot","Survival"],"levels":[{"level":1,"hitDice":"1d10","bab":1,"fort":2,"ref":2,"will":2,"skillPoints":"(8 + Int mod) × 4","cr":1,"special":"Feat, 2 claws 1d4, resistances (acid 5, cold 5, electricity 5, fire 5), dancing lights 1/day"},{"level":2,"hitDice":"2d10","bab":2,"fort":3,"ref":3,"will":3,"skillPoints":"8 + Int mod","cr":2,"special":"+2 Str, +1 natural armor, faerie fire 1/day, darkness 1/day"},{"level":3,"hitDice":"2d10","bab":2,"fort":3,"ref":3,"will":3,"skillPoints":"","cr":2,"special":"+2 Dex, darkness 2/day, bite 1d6"},{"level":4,"hitDice":"3d10","bab":3,"fort":3,"ref":3,"will":3,"skillPoints":"8 + Int mod","cr":3,"special":"+2 Str, +2 Int, desecrate 1/day"},{"level":5,"hitDice":"3d10","bab":3,"fort":3,"ref":3,"will":3,"skillPoints":"","cr":3,"special":"+2 Con, resistances (acid 10, cold 10, electricity 10, fire 10), immunity to poison"},{"level":6,"hitDice":"4d10","bab":4,"fort":4,"ref":4,"will":4,"skillPoints":"8 + Int mod","cr":3,"special":"+2 Str, darkness 3/day"},{"level":7,"hitDice":"4d10","bab":4,"fort":4,"ref":4,"will":4,"skillPoints":"","cr":4,"special":"+2 Str, +3 natural armor, unholy blight 1/day, 2 claws 1d6"},{"level":8,"hitDice":"5d10","bab":5,"fort":4,"ref":4,"will":4,"skillPoints":"8 + Int mod","cr":4,"special":"+2 Dex, darkness 4/day"},{"level":9,"hitDice":"5d10","bab":5,"fort":4,"ref":4,"will":4,"skillPoints":"","cr":5,"special":"+2 Str, Large size, 10-ft. reach, bite 1d8"},{"level":10,"hitDice":"6d10","bab":6,"fort":5,"ref":5,"will":5,"skillPoints":"8 + Int mod","cr":5,"special":"+2 Str, +5 natural armor, resistances (acid 20, cold 20, electricity 20, fire 20)"}]}'::jsonb)
insert into public.catalog_classes (id,name_pt,name_en,description_pt,hp_per_level,key_attributes,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cor.prestige.cor-black-blood-cultist','Black Blood cultist','Black Blood cultist','Chaotic evil, chaotic neutral, or neutral evil; Knowledge (nature) 2 ranks; Survival 8 ranks; Improved Unarmed Strike; Track; Ability to rage',12,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',44,'dnd35','{"id":"cor-black-blood-cultist","name":"Black Blood cultist","hitDie":12,"skillPointsPerLevel":"4 + Int modifier","requirements":{"alignment":"Chaotic evil, chaotic neutral, or neutral evil","skills":["Knowledge (nature) 2 ranks","Survival 8 ranks"],"feats":["Improved Unarmed Strike","Track"],"special":["Ability to rage"]},"classSkills":["Climb","Handle Animal","Hide","Intimidate","Jump","Knowledge (nature)","Listen","Move Silently","Search","Spot","Survival","Swim"],"levels":[{"level":1,"bab":0,"fort":2,"ref":2,"will":0,"special":["Feral rage (claws)","damage reduction 1/silver"]},{"level":2,"bab":1,"fort":3,"ref":3,"will":0,"special":["Improved grapple"]},{"level":3,"bab":2,"fort":3,"ref":3,"will":1,"special":["Feral rage (bite)"]},{"level":4,"bab":3,"fort":4,"ref":4,"will":1,"special":["Scent","DR 3/silver"]},{"level":5,"bab":3,"fort":4,"ref":4,"will":1,"special":["Stranglehold"]},{"level":6,"bab":4,"fort":5,"ref":5,"will":2,"special":["Feral rage (rend)"]},{"level":7,"bab":5,"fort":5,"ref":5,"will":2,"special":["Improved natural attacks"]},{"level":8,"bab":6,"fort":6,"ref":6,"will":2,"special":["Savage grapple"]},{"level":9,"bab":6,"fort":6,"ref":6,"will":3,"special":["DR 5/silver"]},{"level":10,"bab":7,"fort":7,"ref":7,"will":3,"special":["Feral form"]}],"features":[{"name":"Feral Rage (Ex)","text":"Black Blood cultist class levels stack with barbarian levels for purposes of determining your rage ability. Thus, an 8th-level barbarian/4th-level Black Blood cultist can use greater rage four times per day, just as a 12th-level barbarian could. At 1st level, when raging, you gain two claw attacks at your highest base attack bonus. Each claw deals 1d6 points of damage plus your Strength modifier. You can use a one-handed weapon and a claw, but when doing so the claw counts as a secondary weapon (adding only half your Strength bonus to damage, and with a -5 modifier on the attack roll). At 3rd level, you gain a bite attack when raging in addition to your two claw attacks. The claws are still your primary weapons and the bite is your secondary weapon. The bite deals 1d4 points of damage plus half your Strength modifier. You can use a two-handed weapon with your bite as a secondary attack, or you can use a one-handed weapon with your claw and bite as secondary attacks. At 6th level and higher, whenever you hit with both of your claw attacks during a rage, you rend your opponent''s flesh, automatically dealing double claw damage in addition to normal damage."},{"name":"Damage Reduction (Ex)","text":"At 4th level and at 9th level, you gain damage reduction, which stacks with damage reduction from other sources. Silvered weapons ignore the damage reduction granted by levels in this prestige class."},{"name":"Improved Grapple","text":"At 2nd level, you gain the Improved Grapple feat even if you do not meet the prerequisites for it."},{"name":"Scent (Ex)","text":"At 4th level, you gain the scent ability."},{"name":"Stranglehold","text":"At 5th level, you learn to snap the necks of fallen enemies, allowing you to administer a coup de grace with your bite attack as a move action."},{"name":"Improved Natural Attacks","text":"At 7th level, your natural attacks become even more deadly. Your claw attacks now deal 1d8 points of damage and your bite attack deals 1d6 points."},{"name":"Savage Grapple","text":"Starting at 8th level, you deal damage as if you had hit with all your natural weapons (including rend, if you are raging) on a successful grapple check."},{"name":"Feral Form","text":"By 10th level, you have gained great control over your bestial nature. You can now use your claw, bite, and rend attacks even when you are not raging."}]}'::jsonb),
('dnd35.cor.prestige.cor-justice-of-weald-and-woe','Justice of weald and woe','Justice of weald and woe','Craft (bowmaking) 8 ranks; Hide 8 ranks; Knowledge (nature) 4 ranks; Move Silently 8 ranks; Survival 8 ranks; Point Blank Shot; Weapon Focus (longbow); Base attack bonus +6',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',44,'dnd35','{"id":"cor-justice-of-weald-and-woe","name":"Justice of weald and woe","hitDie":8,"skillPointsPerLevel":"4 + Int modifier","requirements":{"skills":["Craft (bowmaking) 8 ranks","Hide 8 ranks","Knowledge (nature) 4 ranks","Move Silently 8 ranks","Survival 8 ranks"],"feats":["Point Blank Shot","Weapon Focus (longbow)"],"special":["Base attack bonus +6"]},"classSkills":["Balance","Bluff","Climb","Concentration","Craft","Disguise","Escape Artist","Gather Information","Handle Animal","Hide","Intimidate","Jump","Knowledge (local)","Knowledge (nature)","Knowledge (religion)","Listen","Sense Motive","Spot","Survival","Swim","Tumble"],"levels":[{"level":1,"bab":0,"fort":3,"ref":3,"will":0,"special":["Spells"]},{"level":2,"bab":1,"fort":3,"ref":3,"will":1,"special":["Bonus feat","woodland stride"]},{"level":3,"bab":2,"fort":4,"ref":4,"will":1,"special":["Sneak attack +1d6"]},{"level":4,"bab":3,"fort":4,"ref":4,"will":1,"special":["Lucky shot","trackless step"]},{"level":5,"bab":3,"fort":5,"ref":5,"will":1,"special":["Poison use"]},{"level":6,"bab":4,"fort":5,"ref":5,"will":2,"special":["Steady hand"]},{"level":7,"bab":5,"fort":6,"ref":6,"will":2,"special":["Sneak attack +2d6"]},{"level":8,"bab":6,"fort":6,"ref":6,"will":2,"special":["Bonus feat"]},{"level":9,"bab":6,"fort":7,"ref":7,"will":3,"special":["Hide in plain sight"]},{"level":10,"bab":7,"fort":7,"ref":7,"will":3,"special":["Death attack","immunity to poison"]}],"spellsPerDay":[[0,null,null,null],[1,null,null,null],[2,0,null,null],[3,1,null,null],[3,2,0,null],[3,3,1,null],[3,3,2,0],[3,3,3,1],[3,3,3,2],[3,3,3,3]],"spellsKnown":[[2,null,null,null],[3,null,null,null],[3,2,null,null],[4,3,null,null],[4,3,2,null],[4,4,3,null],[4,4,3,2],[4,4,4,3],[4,4,4,3],[4,4,4,4]],"spellList":[{"level":1,"spells":["camouflage","detect snares and pits","endure elements","faerie fire","hide from animals","jump","longstrider","obscuring mist","pass without trace","woodwisp arrow*"]},{"level":2,"spells":["barkskin","brilliant energy arrow*","cat''s grace","fog cloud","snare","spellslayer arrow*","speak with plants","spider climb","tree shape"]},{"level":3,"spells":["arrowsplit*","darkflame arrow*","darkvision","meld into stone","serpent arrow*","spike growth","water breathing","wind wall"]},{"level":4,"spells":["bloodfreeze arrow*","doublestrike arrow*","freedom of movement","poison","scrying","shadow arrow*","spike stones","tree stride"]}],"features":[{"name":"Weapon and Armor Proficiency","text":"You gain no proficiency with any weapon, armor, or shield."},{"name":"Spellcasting","text":"You gain spells according to the tables above. You do not gain new spells in any other spellcasting classes that you might have had before you took this prestige class, but you can still cast spells from your previous class. You can only choose spells from the justice spell list; justices use their Wisdom modifier for calculating bonus spells and spell DCs. (Spells known: the first entry of each spell level assumes the character has sufficient Intelligence to have a bonus spell of this level.)"},{"name":"Bonus Feats","text":"At 2nd and 8th levels, you gain a bonus archery feat. When you gain a new bonus feat, you must choose from the following list: Deflect Arrows, Far Shot, Improved Critical (longbow), Improved Precise Shot, Manyshot, Mounted Archery, Precise Shot, Rapid Shot, Shot on the Run, Snatch Arrows, Weapon Specialization (longbow only), Greater Weapon Focus (longbow only), Greater Weapon Specialization (longbow only). You must meet all prerequisites for a bonus feat. Use your justice level when determining whether you meet a prerequisite of a minimum fighter level."},{"name":"Woodland Stride (Ex)","text":"At 2nd level, you can move through any sort of undergrowth, as the druid ability described on page 36 of the Player''s Handbook."},{"name":"Sneak Attack (Ex)","text":"Beginning at 3rd and 7th level, you deal an extra 1d6 points of damage when striking an opponent when the opponent is denied a Dexterity bonus to armor class, such as when it is surprised and flat-footed, or when you attack from a flanking position, as the sneak attack ability of rogues. Your damage dice stack with any sneak attack damage dice you might have gained from a previous class."},{"name":"Lucky Shot (Su)","text":"Once per day as a free action, you can gain a +10 insight bonus to one attack roll with your longbow. You must declare the use of this ability before rolling the die."},{"name":"Trackless Step (Ex)","text":"At 4th level and higher, you leave no trail in natural surroundings and cannot be tracked. You can leave a trail on purpose if you so desire."},{"name":"Poison Use (Ex)","text":"At 5th level, you learn to create and/or extract natural poisons and apply them to your weapons without any danger of harming yourself."},{"name":"Steady Hand (Ex)","text":"At 6th level, you become able to fire your personal longbow in melee combat without provoking attacks of opportunity. You only gain the benefit of this special ability when wearing light or no armor."},{"name":"Hide in Plain Sight (Ex)","text":"At 9th level, you gain the ability to hide in plain sight, as the ranger ability described on page 48 of the Player''s Handbook."},{"name":"Death Attack (Ex)","text":"At 10th level, you gain the ability to study your victim for 3 rounds and then make a sneak attack with a longbow that, if it successfully deals damage, has the additional effect of possibly either paralyzing or killing the target (your choice). While studying the victim, you can undertake other actions so long as your attention stays focused on the target and the target does not detect you or recognize you as an enemy. If the victim of such an attack fails a Fortitude save (DC 20 + your Int modifier) against the kill effect, it dies. If the saving throw fails against the paralysis effect, the target is rendered helpless and unable to act for 1d6+10 rounds. If the target''s saving throw succeeds, the attack is just a normal sneak attack. Once you have completed the 3 rounds of study, you must make the death attack within the next 3 rounds. If a death attack is attempted and fails (the victim makes her save) or if you do not launch the attack within 3 rounds of completing the study, 3 new rounds of study are required before you can attempt another death attack."},{"name":"Poison Immunity (Ex)","text":"At 10th level, you gain immunity to all natural poisons and animal venoms. This ability differs from the druid ability of the same name, in that it only applies to poisons derived from natural plants or fungi, or from animal or vermin venoms, not to all poisons, such as venoms from celestial animals or outsiders, or poisons derived from minerals or magic."}]}'::jsonb),
('dnd35.cor.prestige.cor-night-mask-deathbringer','Night Mask deathbringer','Night Mask deathbringer','Any evil; Hide 8 ranks; Knowledge (local) 3 ranks; Move Silently 8 ranks; Great Fortitude; Evasion and uncanny dodge class features',6,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',44,'dnd35','{"id":"cor-night-mask-deathbringer","name":"Night Mask deathbringer","hitDie":6,"skillPointsPerLevel":"8 + Int modifier","requirements":{"alignment":"Any evil","skills":["Hide 8 ranks","Knowledge (local) 3 ranks","Move Silently 8 ranks"],"feats":["Great Fortitude"],"special":["Evasion and uncanny dodge class features"]},"classSkills":["Balance","Bluff","Climb","Craft","Decipher Script","Diplomacy","Disable Device","Disguise","Escape Artist","Forgery","Gather Information","Hide","Intimidate","Jump","Knowledge (local)","Listen","Move Silently","Open Lock","Perform","Profession","Search","Sense Motive","Sleight of Hand","Spot","Swim","Tumble","Use Magic Device","Use Rope"],"levels":[{"level":1,"bab":0,"fort":0,"ref":2,"will":0,"special":["Creature of darkness","hesitating stare 1/day","light sensitivity","spider climb"]},{"level":2,"bab":1,"fort":0,"ref":3,"will":0,"special":["Feral senses (low-light vision)"]},{"level":3,"bab":2,"fort":1,"ref":3,"will":1,"special":["Speak with creatures of the night","ghost step 1/day"]},{"level":4,"bab":3,"fort":1,"ref":4,"will":1,"special":["Hesitating stare 2/day","lesser blood bond","sneak attack +1d6"]},{"level":5,"bab":3,"fort":1,"ref":4,"will":1,"special":["Improved evasion"]},{"level":6,"bab":4,"fort":2,"ref":5,"will":2,"special":["Slippery mind","ghost step 2/day"]},{"level":7,"bab":5,"fort":2,"ref":5,"will":2,"special":["Hesitating stare 3/day","feral senses (darkvision)"]},{"level":8,"bab":6,"fort":2,"ref":6,"will":2,"special":["Sneak attack +2d6"]},{"level":9,"bab":6,"fort":3,"ref":6,"will":3,"special":["Ghost step 3/day"]},{"level":10,"bab":7,"fort":3,"ref":7,"will":3,"special":["Hesitating stare 4/day","greater blood bond"]}],"features":[{"name":"Creature of Darkness (Ex)","text":"Animals can sense the death in you, causing them to fear your presence. As a result, all animals except for bats, rats, and wolves have their initial attitudes moved down one category when you first approach them. In addition, you take a -2 penalty on all Ride checks due to the beast''s inherent nervousness at your presence."},{"name":"Hesitating Stare (Su)","text":"Deathbringers can force their opponents to confront their own mortality with but a glance. This ability can be activated once per day at any time, even when you are surprised. You cast a glance at any foe within 30 feet, who must then make a successful Will save (DC 10 + 1/2 your class level + Cha modifier) or be stunned for 1 round. You can use this ability twice per day at 4th level and higher, three times per day at 7th level and higher, and four times per day at 10th level."},{"name":"Light Sensitivity (Ex)","text":"In sunlight or bright magical light (such as a daylight spell), a deathbringer is dazzled."},{"name":"Spider Climb (Sp)","text":"Starting at 1st level, you can act as if you were under the influence of a spider climb spell (caster level equals your deathbringer class level). You can use this ability a number of times per day equal to your Charisma modifier, minimum one."},{"name":"Feral Senses","text":"At 2nd level, you gain low-light vision—the ability to see twice as far as a human in starlight, moonlight, torchlight, or similar conditions of poor illumination. You retain the ability to distinguish color and detail under these conditions. At 7th level, you gain darkvision out to 60 feet."},{"name":"Speak with Creatures of the Night (Ex)","text":"When you reach 3rd level, you can speak with rats, bats, and wolves as if you were under the influence of a speak with animals spell. This ability does nothing to affect the attitude of such creatures."},{"name":"Ghost Step (Su)","text":"Once per day starting at 3rd level, you can make yourself invisible for 1 round. This is a swift action (something you can do as a free action once per round) that does not provoke attacks of opportunity. You can use this ability twice per day at 6th level and higher, and three times per day at 9th level and higher."},{"name":"Lesser Blood Bond (Su)","text":"To use this ability, a deathbringer of 4th level or higher must get the target to drink three drops of her blood. She can do this by hiding the blood in food or drink, or by pinning the target for 1 round and bleeding directly into his mouth. Once this condition has been fulfilled, the deathbringer can cause a charm person effect to come over the target by speaking directly to him. The words used are unimportant, only that the deathbringer wills the target to be friendly to her. The caster level of the effect equals the deathbringer''s class level, and the DC to resist the effect equals 10 + the deathbringer''s class level + Cha modifier. You can have a number of outstanding blood bonds, active or not, equal to your Charisma modifier. Should you exceed this limit, the oldest blood bond becomes inactive."},{"name":"Sneak Attack (Ex)","text":"At 4th level and higher, you deal extra damage when you catch a foe flat-footed or flank a foe, as the rogue class feature described on page 50 of the Player''s Handbook. Sneak-attack dice attained from multiple sources stack."},{"name":"Improved Evasion (Ex)","text":"At 5th level, your pseudo-vampiric celerity grants you supernatural reflexes. You now take no damage on a successful Reflex saving throw against area attacks and half damage on a failed save. You do not gain the benefit of this ability if you are helpless."},{"name":"Slippery Mind (Su)","text":"When you attain 6th level, your mind is only partly mortal, allowing you to shrug off mental attacks and compulsions more easily than others. Any time you are affected by an enchantment spell or effect and you fail your saving throw, you can attempt the save again 1 round later at the same DC. You only get one extra chance to succeed per effect."},{"name":"Greater Blood Bond (Su)","text":"This ability, acquired at 10th level, works just like lesser blood bond, except the target comes under the influence of a dominate person spell rather than charm person."}]}'::jsonb),
('dnd35.cor.prestige.cor-shade-hunter','Shade hunter','Shade hunter','Any evil; Climb 4 ranks; Decipher Script 4 ranks; Disable Device 5 ranks; Jump 4 ranks; Knowledge (dungeoneering) 6 ranks; Knowledge (history) 2 ranks; Search 8 ranks; Speak Language (Netherese); Survival 6 ranks; Use Magic Device 5 ranks; Track; Shades as a favored enemy; trapfinding class feature',8,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',44,'dnd35','{"id":"cor-shade-hunter","name":"Shade hunter","hitDie":8,"skillPointsPerLevel":"8 + Int modifier","requirements":{"alignment":"Any evil","skills":["Climb 4 ranks","Decipher Script 4 ranks","Disable Device 5 ranks","Jump 4 ranks","Knowledge (dungeoneering) 6 ranks","Knowledge (history) 2 ranks","Search 8 ranks","Speak Language (Netherese)","Survival 6 ranks","Use Magic Device 5 ranks"],"feats":["Track"],"special":["Shades as a favored enemy","trapfinding class feature"]},"classSkills":["Balance","Climb","Concentration","Decipher Script","Disable Device","Disguise","Gather Information","Hide","Jump","Knowledge (arcana)","Knowledge (dungeoneering)","Knowledge (geography)","Knowledge (history)","Knowledge (local)","Listen","Move Silently","Open Lock","Profession","Ride","Search","Spot","Survival","Swim","Tumble","Use Magic Device","Use Rope"],"levels":[{"level":1,"bab":0,"fort":2,"ref":2,"will":0,"special":["Trap sense +1","tricks of the trade"]},{"level":2,"bab":1,"fort":3,"ref":3,"will":0,"special":["Low-light vision","sense ancient magic"]},{"level":3,"bab":2,"fort":3,"ref":3,"will":1,"special":["Trap sense +2","expert packer"]},{"level":4,"bab":3,"fort":4,"ref":4,"will":1,"special":["Sneak attack +1d6","tools of the trade"]},{"level":5,"bab":3,"fort":4,"ref":4,"will":1,"special":["Trap sense +3","darkvision 60 ft."]},{"level":6,"bab":4,"fort":5,"ref":5,"will":2,"special":["Special ability"]},{"level":7,"bab":5,"fort":5,"ref":5,"will":2,"special":["Trap sense +4","locate ancient magic"]},{"level":8,"bab":6,"fort":6,"ref":6,"will":2,"special":["Sneak attack +2d6","improved favored enemy"]},{"level":9,"bab":6,"fort":6,"ref":6,"will":3,"special":["Trap sense +5"]},{"level":10,"bab":7,"fort":7,"ref":7,"will":3,"special":["Blindsight 30 ft."]}],"spellsPerDay":[[0,null,null,null],[1,null,null,null],[2,0,null,null],[3,1,null,null],[3,2,0,null],[3,3,1,null],[3,3,2,0],[3,3,3,1],[3,3,3,2],[3,3,3,3]],"spellsKnown":[[2,null,null,null],[3,null,null,null],[3,2,null,null],[4,3,null,null],[4,3,2,null],[4,4,3,null],[4,4,3,2],[4,4,4,3],[4,4,4,3],[4,4,4,4]],"spellList":[{"level":1,"spells":["camouflage","delay poison","detect snares and pits","identify","jump","longstrider","pass without trace","read magic","sure-footed"]},{"level":2,"spells":["bear''s endurance","bull''s strength","cat''s grace","cure moderate wounds","detect metals and minerals","make whole","snare"]},{"level":3,"spells":["continual flame","daylight","locate object","neutralize poison","obscure object","remove disease"]},{"level":4,"spells":["commune with nature","dispel magic","freedom of movement","nondetection","remove curse","stone shape"]}],"features":[{"name":"Spellcasting","text":"When you take up this class, you gain the ability to cast a number of arcane spells. To cast a spell, you must have an Intelligence score of 10 + the spell''s level. Your bonus spells are based on Intelligence, and saving throws against these spells have a DC of 10 + spell level + your Intelligence bonus. When you get 0 spells per day, you gain only the bonus spells you would be entitled to based on your intelligence score for that spell level. You cast spells just as a sorcerer does. Upon reaching 6th level, and at every even-numbered level after that, you can choose to learn a new spell in place of one you already know. The new spell''s level must be the same as that of the spell being exchanged, and it must be at least two levels lower than the highest-level shade hunter spell you can cast."},{"name":"Trap Sense (Ex)","text":"Your expertise with dungeons gives you an intuitive sense that alerts you to danger from traps, providing you with a +1 bonus on Reflex saves made to avoid traps and a +1 dodge bonus to AC against attacks made by traps. These bonuses increase by 1 every other level, up to +5 at 9th level. Trap sense bonuses gained from multiple sources stack."},{"name":"Tricks of the Trade (Ex)","text":"The experiences and dangers that you have encountered in your travels begin to coalesce into a practical body of knowledge when you enter the shade hunter class. This knowledge grants you a bonus equal to your class level that can be used each day to augment ability checks, skill checks, or attack rolls. The points of bonus do not need to be applied to the same roll, and you can divide them up however you like throughout the day. You must decide whether or not to use a bonus, and if so how large the bonus will be, before you roll the die. For example, a 3rd-level shade hunter has a total bonus of +3 to distribute. If he finds himself in mortal combat, he could apply the entire bonus to a single attack roll, hoping to fell his enemy. Alternatively, he could apply a +1 bonus to an Open Lock check, then another +1 to a Spot check later that day, and his final +1 bonus to a Strength check to dislodge a coffer from its resting place."},{"name":"Low-Light Vision (Ex)","text":"At 2nd level, you gain low-light vision. If you already have low-light vision, its effective distance is doubled, so you can now see four times as far as a human in conditions of low light."},{"name":"Sense Ancient Magic (Su)","text":"Starting at 2nd level, you can detect the magical aura radiated by items of Netherese creation. This ability functions like detect magic, except that it is always active unless you consciously suppress it, and it can only detect the auras of magic items that have been in the same location for at least one hundred years."},{"name":"Expert Packer","text":"Starting at 3rd level, you have learned how to get every last bit of utility out of your backpack, belt, and bandoleer. Reduce the weight of your gear by 10% for purposes of figuring your load."},{"name":"Sneak Attack (Ex)","text":"At 4th level and higher, you deal extra damage when you catch a foe flat-footed or flank a foe, as the rogue class feature described on page 50 of the Player''s Handbook. Sneak-attack dice attained from multiple sources stack."},{"name":"Tools of the Trade","text":"By 4th level, you have picked up so many knickknacks and strange tools on your travels that you''ve lost track of everything you own. Once per day, you can \"find\" any mundane piece of equipment (other than weapons or armor) worth up to 10 gp per class level somewhere on your person, having forgotten completely about it. When you do so, you subtract an equivalent amount of gold (or other treasure—gems, jewelry, art, etc.) from your savings. If you do not have enough gold to cover the cost of the item you want, you might not find the item with this ability."},{"name":"Darkvision (Ex)","text":"At 5th level, you gain darkvision out to 60 feet. If you already have darkvision, its effective distance extends by an additional 60 feet instead."},{"name":"Special Ability (Ex)","text":"At 6th level, you can choose one of the following rogue special abilities: defensive roll, improved evasion, or skill mastery (see Player''s Handbook page 51)."},{"name":"Locate Ancient Magic (Su)","text":"When you reach 7th level, your ability to sense the lost magic of Netheril has grown stronger. You can now locate any magic items that have been in the same location for at least one hundred years as if you had cast a locate object spell and were familiar with the items in question. Activating this ability is a standard action, and you can locate multiple auras by concentrating for continuous rounds."},{"name":"Improved Favored Enemy (Ex)","text":"Starting at 8th level, your favored enemy bonuses against shades increase by 2. No other favored enemy bonuses can be increased with this ability."},{"name":"Blindsight (Ex)","text":"At 10th level your ability to function in the deepest, darkest dungeons grants you the ability to sense your surroundings using every available sensory input. You gain blindsight out to 30 feet."}]}'::jsonb),
('dnd35.cor.prestige.cor-thayan-gladiator','Thayan gladiator','Thayan gladiator','Any evil; Toughness; Weapon Focus (natural weapon); Base attack bonus +5; Must possess at least one natural weapon; Must undergo a ritual developed by the Zulkir of Transmutation that grants the class its abilities',12,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',44,'dnd35','{"id":"cor-thayan-gladiator","name":"Thayan gladiator","hitDie":12,"skillPointsPerLevel":"2 + Int modifier","requirements":{"alignment":"Any evil","skills":[],"feats":["Toughness","Weapon Focus (natural weapon)"],"special":["Base attack bonus +5","Must possess at least one natural weapon","Must undergo a ritual developed by the Zulkir of Transmutation that grants the class its abilities"]},"classSkills":["Bluff","Climb","Intimidate","Jump","Sense Motive","Spot"],"levels":[{"level":1,"bab":1,"fort":2,"ref":0,"will":0,"special":["Improved natural attack","study opponent"]},{"level":2,"bab":2,"fort":3,"ref":0,"will":0,"special":["Improved critical","natural armor +1"]},{"level":3,"bab":3,"fort":3,"ref":1,"will":1,"special":["Stunning critical","silver strike"]},{"level":4,"bab":4,"fort":4,"ref":1,"will":1,"special":["Natural weapon focus"]},{"level":5,"bab":5,"fort":4,"ref":1,"will":1,"special":["Imbue natural weapon","natural armor +2"]},{"level":6,"bab":6,"fort":5,"ref":2,"will":2,"special":["Adamantine strike"]},{"level":7,"bab":7,"fort":5,"ref":2,"will":2,"special":["Savage strike"]},{"level":8,"bab":8,"fort":6,"ref":2,"will":2,"special":["Natural armor +3","natural weapon mastery"]},{"level":9,"bab":9,"fort":6,"ref":3,"will":3,"special":["Magic strike"]},{"level":10,"bab":10,"fort":7,"ref":3,"will":3,"special":["Imbue natural weapon"]}],"features":[{"name":"Improved Natural Attack","text":"When you enter this class, choose one of your natural weapons to gain the benefits of the Improved Natural Attack feat. The natural weapon you choose is affected by the rest of the abilities you gain through advancing in this class."},{"name":"Study Opponent (Ex)","text":"You prefer to circle your opponents before engaging them in melee, searching them for weaknesses and noting the way their bodies move. You can study any opponent within 30 feet as a standard action for a number of rounds equal to your Wisdom modifier (minimum 1 round). For each round you study, you gain a +1 bonus on attack rolls and AC during the round that you first engage them in melee combat."},{"name":"Improved Critical","text":"At 2nd level, your improved natural attack gains the benefit of the Improved Critical feat."},{"name":"Natural Armor","text":"Beginning at 2nd level, your natural armor improves by 1 point to help you withstand the awesome blows of your gladiatorial opponents. At 5th and 8th levels, your natural armor improves by an additional point."},{"name":"Stunning Critical (Ex)","text":"Starting at 3rd level, any time you make a successful critical hit with your chosen natural weapon, your enemy must succeed on a Fortitude save (DC 15 + your Str modifier) or be stunned for 1 round."},{"name":"Silver Strike (Ex)","text":"At 3rd level, attacks from your chosen natural weapon overcome damage reduction as if they were silvered weapons."},{"name":"Natural Weapon Focus (Ex)","text":"At 4th level, you gain the ability to make an additional strike at a -5 penalty with your chosen natural weapon when you use a full attack action."},{"name":"Imbue Natural Weapon (Su)","text":"At 5th level, your chosen natural weapon gains a special ability as if it were a magic weapon. Choose one special ability from the following list and apply it to your natural weapon(s): flaming, frost, ghost touch, shock, or thundering. At 10th level, the ritual you underwent upon becoming a Thayan gladiator grants you a final power from the following list to apply to your chosen natural weapon: anarchic*, axiomatic*, disruption, flaming burst, icy burst, shocking burst, speed**, unholy, or wounding. *In order to choose one of these, the Thayan gladiator''s alignment must match the appropriate ability (the character must be chaotic to choose anarchic or lawful to choose axiomatic). **The effect of this ability stacks with the additional attack gained from the natural weapon focus ability."},{"name":"Adamantine Strike (Ex)","text":"At 6th level, attacks from your chosen natural weapon overcome damage reduction as if they were adamantine weapons."},{"name":"Savage Strike (Ex)","text":"At 7th level, the critical multiplier for your chosen natural weapon increases by one. Thus, if you had a critical multiplier of x2, it would become x3; if it was already x3, it becomes x4."},{"name":"Natural Weapon Mastery (Ex)","text":"Starting at 8th level, the extra attack you gain from natural weapon focus is at your highest base attack bonus."},{"name":"Magic Strike (Ex)","text":"At 9th level and higher, attacks from your chosen natural weapon overcome damage reduction as if they were magic weapons."}]}'::jsonb),
('dnd35.cor.prestige.cor-vengeance-knight','Vengeance knight','Vengeance knight','Lawful evil, lawful neutral, or neutral evil; Intimidate 6 ranks; Ride 4 ranks; Sense Motive 2 ranks; Iron Will; Weapon Focus (any sword); Base attack bonus +5; Proficiency with heavy armor and heavy shields',10,ARRAY[]::text[],ARRAY['prestige']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',44,'dnd35','{"id":"cor-vengeance-knight","name":"Vengeance knight","hitDie":10,"skillPointsPerLevel":"2 + Int modifier","requirements":{"alignment":"Lawful evil, lawful neutral, or neutral evil","skills":["Intimidate 6 ranks","Ride 4 ranks","Sense Motive 2 ranks"],"feats":["Iron Will","Weapon Focus (any sword)"],"special":["Base attack bonus +5","Proficiency with heavy armor and heavy shields"]},"classSkills":["Climb","Craft","Gather Information","Intimidate","Jump","Knowledge (local)","Ride","Search","Sense Motive","Spot"],"levels":[{"level":1,"bab":1,"fort":2,"ref":0,"will":0,"special":["Armor training","bringer of vengeance +1"]},{"level":2,"bab":2,"fort":3,"ref":0,"will":0,"special":["Counterstrike +1","Improved Shield Bash"]},{"level":3,"bab":3,"fort":3,"ref":1,"will":1,"special":["Bonus feat"]},{"level":4,"bab":4,"fort":4,"ref":1,"will":1,"special":["Arcane backlash 1d6"]},{"level":5,"bab":5,"fort":4,"ref":1,"will":1,"special":["Bringer of vengeance +2"]},{"level":6,"bab":6,"fort":5,"ref":2,"will":2,"special":["Improved armor training"]},{"level":7,"bab":7,"fort":5,"ref":2,"will":2,"special":["Arcane backlash 2d6"]},{"level":8,"bab":8,"fort":6,"ref":2,"will":2,"special":["Counterstrike +2"]},{"level":9,"bab":9,"fort":6,"ref":3,"will":3,"special":["Bonus feat","bringer of vengeance +3"]},{"level":10,"bab":10,"fort":7,"ref":3,"will":3,"special":["Arcane backlash 3d6","superior armor training"]}],"features":[{"name":"Armor Training (Ex)","text":"As a vengeance knight, you always wear the heaviest armor available to you, and thus you learn to wear it more effectively through training. Your armor check penalty imposed by heavy armor and shields for all skills except Swim is reduced by 1, and you can don your armor as if you had help (although you still require a servant to help you don half-plate or full plate). At 6th level, your armor check penalty for armor is reduced by 3, and you can make a DC 15 Constitution check to avoid being fatigued from sleeping in your armor. In addition, you take only half the normal movement penalty for wearing heavy armor. At 10th level, you have truly mastered the art of wearing heavy armor. You can now sleep in your armor without penalty, and your armor check penalties for armor are reduced by 5. In addition, you can don half-plate or plate mail without assistance, although it takes twice the indicated time."},{"name":"Bringer of Vengeance (Ex)","text":"As an agent for the Knights of the Shield, you are often called upon to avenge some slight or to send a message to an enemy of the organization. Whenever you have a specific target, you gain the indicated bonus on Intimidate, Search, Sense Motive, and Spot checks when using these skills against your target. In addition, you gain the indicated bonus on all attack rolls and damage rolls against the target. (+1 at 1st level, +2 at 5th level, +3 at 9th level.)"},{"name":"Counterstrike (Ex)","text":"Vengeance knights visit pain upon those who would hurt them. As a result, you gain the indicated bonus on all melee attack rolls and damage rolls against any creature that damaged you in the previous round. This bonus stacks with that from your bringer of vengeance ability. (+1 at 2nd level, +2 at 8th level.)"},{"name":"Improved Shield Bash","text":"At 2nd level, you gain the Improved Shield Bash feat, even if you do not meet the prerequisites."},{"name":"Bonus Feat","text":"At 3rd and 9th levels, you can choose a bonus feat from the fighter''s bonus feat list."},{"name":"Arcane Backlash (Su)","text":"Any time you successfully save against any arcane spell when you are the spell''s only target, the original caster takes the indicated amount of nonlethal damage as you lash the energies of his failed spell back at him. (1d6 at 4th level, 2d6 at 7th level, 3d6 at 10th level.)"}]}'::jsonb)
insert into public.catalog_feats (id,feat_type,level,name_pt,name_en,description_pt,prerequisites,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cor.feat.cor-bloodsoaked-intimidate','General',1,'Bloodsoaked Intimidate','Bloodsoaked Intimidate','When you collect a trophy using the Snatch Trophy feat, you can make an Intimidate check as a swift action against an adjacent opponent who witnesses your savage act.','Snatch Trophy',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-bloodsoaked-intimidate","name":"Bloodsoaked Intimidate","type":"General","prerequisites":"Snatch Trophy","benefit":"When you collect a trophy using the Snatch Trophy feat, you can make an Intimidate check as a swift action against an adjacent opponent who witnesses your savage act.","normal":"Making an Intimidate check in combat is a standard action."}'::jsonb),
('dnd35.cor.feat.cor-chakram-ricochet','General',1,'Chakram Ricochet','Chakram Ricochet','If you hit a creature with a thrown chakram, you can cause it to ricochet and strike a secondary target in an adjacent square (within 5 feet of the primary target). You immediately make an attack roll against the secondary target, at a -2 penalty. If the attack hits, you deal damage normally.','Dex 13, base attack bonus +1, proficient with chakram',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-chakram-ricochet","name":"Chakram Ricochet","type":"General","prerequisites":"Dex 13, base attack bonus +1, proficient with chakram","benefit":"If you hit a creature with a thrown chakram, you can cause it to ricochet and strike a secondary target in an adjacent square (within 5 feet of the primary target). You immediately make an attack roll against the secondary target, at a -2 penalty. If the attack hits, you deal damage normally.","special":"A rogue with Chakram Ricochet can deal sneak attack damage to both targets if they are within 30 feet and denied their Dexterity bonus to AC."}'::jsonb),
('dnd35.cor.feat.cor-craven','General',1,'Craven','Craven','You take a -2 penalty on saving throws against fear effects. However, when making a sneak attack, you deal an extra 1 point of damage per character level.','Sneak attack class feature, cannot be immune to fear',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-craven","name":"Craven","type":"General","prerequisites":"Sneak attack class feature, cannot be immune to fear","benefit":"You take a -2 penalty on saving throws against fear effects. However, when making a sneak attack, you deal an extra 1 point of damage per character level."}'::jsonb),
('dnd35.cor.feat.cor-dire-flail-smash','General',1,'Dire Flail Smash','Dire Flail Smash','If you hit the same creature with both ends of your dire flail in the same round, it must make a Fortitude saving throw (DC 10 + 1/2 your character level + your Str modifier) or be dazed by the pain for 1 round.','Str 13, Improved Sunder, Power Attack, Weapon Focus (dire flail)',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-dire-flail-smash","name":"Dire Flail Smash","type":"General","prerequisites":"Str 13, Improved Sunder, Power Attack, Weapon Focus (dire flail)","benefit":"If you hit the same creature with both ends of your dire flail in the same round, it must make a Fortitude saving throw (DC 10 + 1/2 your character level + your Str modifier) or be dazed by the pain for 1 round.","fighterBonus":true}'::jsonb),
('dnd35.cor.feat.cor-dirty-rat','General',1,'Dirty Rat','Dirty Rat','You gain an additional +1 bonus on attack rolls when flanking an opponent.','Tumble 4 ranks',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-dirty-rat","name":"Dirty Rat","type":"General","prerequisites":"Tumble 4 ranks","benefit":"You gain an additional +1 bonus on attack rolls when flanking an opponent."}'::jsonb),
('dnd35.cor.feat.cor-feral-animal-companion','General',1,'Feral Animal Companion','Feral Animal Companion','Instead of calling a normal animal companion, you can call a feral animal companion that foams at the mouth. Any creature harmed by the animal''s bite attack must succeed on a DC 15 Fortitude save or contract red ache (see Dungeon Master''s Guide page 292). The disease has no harmful effect on the feral animal. In addition, your feral animal companion gains a +2 bonus to Strength and Constitution. Attempts by others to influence your feral animal companion with Handle Animal checks take a -10 penalty.','Animal companion class feature, evil alignment',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-feral-animal-companion","name":"Feral Animal Companion","type":"General","prerequisites":"Animal companion class feature, evil alignment","benefit":"Instead of calling a normal animal companion, you can call a feral animal companion that foams at the mouth. Any creature harmed by the animal''s bite attack must succeed on a DC 15 Fortitude save or contract red ache (see Dungeon Master''s Guide page 292). The disease has no harmful effect on the feral animal. In addition, your feral animal companion gains a +2 bonus to Strength and Constitution. Attempts by others to influence your feral animal companion with Handle Animal checks take a -10 penalty.","special":"This feat does not transform a normal animal companion into a feral animal companion."}'::jsonb),
('dnd35.cor.feat.cor-flay-foe','General',1,'Flay Foe','Flay Foe','If you hit the same enemy more than once in a single round with a slashing melee weapon, you deal an extra point of damage with each hit after the first.','Str 15, base attack bonus +6, proficient with slashing melee weapon',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-flay-foe","name":"Flay Foe","type":"General","prerequisites":"Str 15, base attack bonus +6, proficient with slashing melee weapon","benefit":"If you hit the same enemy more than once in a single round with a slashing melee weapon, you deal an extra point of damage with each hit after the first.","fighterBonus":true}'::jsonb),
('dnd35.cor.feat.cor-improved-fiendish-servant','General',1,'Improved Fiendish Servant','Improved Fiendish Servant','Add the following creatures to your list of eligible fiendish servants: ape, black bear, boar, crocodile, dire badger, dire bat, dire weasel, heavy warhorse, leopard, monitor lizard, constrictor snake, Large viper snake, wolverine. In addition, any fiendish servant you call has the fiendish creature template (Monster Manual page 107). The fiendish servant otherwise conforms to the rules in the Dungeon Master''s Guide (page 183).','Fiendish servant class feature',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-improved-fiendish-servant","name":"Improved Fiendish Servant","type":"General","prerequisites":"Fiendish servant class feature","benefit":"Add the following creatures to your list of eligible fiendish servants: ape, black bear, boar, crocodile, dire badger, dire bat, dire weasel, heavy warhorse, leopard, monitor lizard, constrictor snake, Large viper snake, wolverine. In addition, any fiendish servant you call has the fiendish creature template (Monster Manual page 107). The fiendish servant otherwise conforms to the rules in the Dungeon Master''s Guide (page 183)."}'::jsonb),
('dnd35.cor.feat.cor-malign-spell-focus','General',1,'Malign Spell Focus','Malign Spell Focus','Add +1 to the DC for all saving throws against any of your spells that have the evil descriptor.','Any evil alignment',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-malign-spell-focus","name":"Malign Spell Focus","type":"General","prerequisites":"Any evil alignment","benefit":"Add +1 to the DC for all saving throws against any of your spells that have the evil descriptor.","special":"This feat originally appeared in Book of Vile Darkness and has been revised for D&D v.3.5."}'::jsonb),
('dnd35.cor.feat.cor-mortifying-attack','General',1,'Mortifying Attack','Mortifying Attack','All creatures within 30 feet that witness you make a successful death attack must succeed on a Will save (DC equal to death attack damage dealt) or be shaken for 2d4 rounds. Any creature you consider your ally is unaffected. In addition, creatures that fail the save are so horrified by the attack that they lose their Dexterity bonus to Armor Class for 1 round. The target of the death attack must also make the saving throw if it survives. This extraordinary ability is a fear effect.','Death attack class feature',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-mortifying-attack","name":"Mortifying Attack","type":"General","prerequisites":"Death attack class feature","benefit":"All creatures within 30 feet that witness you make a successful death attack must succeed on a Will save (DC equal to death attack damage dealt) or be shaken for 2d4 rounds. Any creature you consider your ally is unaffected. In addition, creatures that fail the save are so horrified by the attack that they lose their Dexterity bonus to Armor Class for 1 round. The target of the death attack must also make the saving throw if it survives. This extraordinary ability is a fear effect."}'::jsonb),
('dnd35.cor.feat.cor-mutilator','General',1,'Mutilator','Mutilator','After delivering the killing blow to a creature (that is, reducing it to -10 hit points) with a melee weapon, you can decapitate or otherwise hack apart the corpse as a free action. Doing so does not provoke attacks of opportunity and ensures that the creature cannot be revived using a raise dead spell. You can mutilate only one enemy per round in this fashion.','Base attack bonus +4, any evil alignment',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-mutilator","name":"Mutilator","type":"General","prerequisites":"Base attack bonus +4, any evil alignment","benefit":"After delivering the killing blow to a creature (that is, reducing it to -10 hit points) with a melee weapon, you can decapitate or otherwise hack apart the corpse as a free action. Doing so does not provoke attacks of opportunity and ensures that the creature cannot be revived using a raise dead spell. You can mutilate only one enemy per round in this fashion."}'::jsonb),
('dnd35.cor.feat.cor-natural-bully','General',1,'Natural Bully','Natural Bully','All enemies within 30 feet of you that have one-half your Hit Dice or less are bullied; they take a -2 morale penalty on attack rolls made against you. A bullied enemy that succeeds in hitting and damaging you is no longer subject to the penalty and cannot be bullied by you for 24 hours. Creatures immune to fear effects cannot be bullied and do not take the penalty on attack rolls to hit you.','Intimidate 6 ranks',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-natural-bully","name":"Natural Bully","type":"General","prerequisites":"Intimidate 6 ranks","benefit":"All enemies within 30 feet of you that have one-half your Hit Dice or less are bullied; they take a -2 morale penalty on attack rolls made against you. A bullied enemy that succeeds in hitting and damaging you is no longer subject to the penalty and cannot be bullied by you for 24 hours. Creatures immune to fear effects cannot be bullied and do not take the penalty on attack rolls to hit you."}'::jsonb),
('dnd35.cor.feat.cor-node-sensitive','Node',1,'Node Sensitive','Node Sensitive','You automatically note the presence of any node to which you are attuned within 30 feet.','—',ARRAY['node']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-node-sensitive","name":"Node Sensitive","type":"Node","prerequisites":"—","benefit":"You automatically note the presence of any node to which you are attuned within 30 feet.","normal":"A creature without this feat that comes within 30 feet of the outermost layer of a node can make a DC 20 Intelligence check to note the presence of the node. A creature with the appropriate Node Spellcasting feat can attempt either an Intelligence check or a Spellcraft check at the same DC to notice the node."}'::jsonb),
('dnd35.cor.feat.cor-node-spellcasting','Node',1,'Node Spellcasting','Node Spellcasting','You are attuned to one type of node and the magical power it provides. When you choose this feat, choose a type of node (earth, evil, or Shadow Weave). This feat grants you access to the various node magic feats and node powers, and allows you to make a Spellcraft check instead of an Intelligence check to notice nearby nodes of the type to which you are attuned.','Caster level 1st',ARRAY['node']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-node-spellcasting","name":"Node Spellcasting","type":"Node","prerequisites":"Caster level 1st","benefit":"You are attuned to one type of node and the magical power it provides. When you choose this feat, choose a type of node (earth, evil, or Shadow Weave). This feat grants you access to the various node magic feats and node powers, and allows you to make a Spellcraft check instead of an Intelligence check to notice nearby nodes of the type to which you are attuned.","normal":"A creature without this feat cannot take other node-related feats, cannot access a node''s full potential, and must make an Intelligence check to notice nearby nodes or to manipulate node powers.","special":"You can gain this feat multiple times. Each time you take the feat, it attunes you to a different node type."}'::jsonb),
('dnd35.cor.feat.cor-node-defense','Node',1,'Node Defense','Node Defense','You receive an insight bonus to your Armor Class and on saving throws equal to the class of any node that you currently occupy and to which you are attuned, up to a maximum of +4. For example, if you are inside the middle (+2) layer of a Class 3 node, you gain a +2 bonus.','Node Spellcasting, caster level 1st',ARRAY['node']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-node-defense","name":"Node Defense","type":"Node","prerequisites":"Node Spellcasting, caster level 1st","benefit":"You receive an insight bonus to your Armor Class and on saving throws equal to the class of any node that you currently occupy and to which you are attuned, up to a maximum of +4. For example, if you are inside the middle (+2) layer of a Class 3 node, you gain a +2 bonus."}'::jsonb),
('dnd35.cor.feat.cor-node-store','Node',1,'Node Store','Node Store','Each time you take this feat, choose two spells of any level that you know and can cast. If you are a spellcaster who prepares spells, you can now prepare those two spells in addition to your normal spell complement as long as you are in a node to which you are attuned, just as if you had two extra spell slots per day. These extra prepared spells are stored in the node instead of in your mind. You can cast them normally while you are within that node, even if you have left the node and returned since storing them there. These extra prepared spells are stored in the node instead of in your mind. You can cast them normally while you are within that node, even if you have left the node and returned since storing them there. Spellcasters who do not prepare spells: see COR_NODE_STORE_REST (dnd35CorSpellLists.ts, p. 26).','Node Spellcasting, caster level 1st',ARRAY['node']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-node-store","name":"Node Store","type":"Node","prerequisites":"Node Spellcasting, caster level 1st","benefit":"Each time you take this feat, choose two spells of any level that you know and can cast. If you are a spellcaster who prepares spells, you can now prepare those two spells in addition to your normal spell complement as long as you are in a node to which you are attuned, just as if you had two extra spell slots per day. These extra prepared spells are stored in the node instead of in your mind. You can cast them normally while you are within that node, even if you have left the node and returned since storing them there. These extra prepared spells are stored in the node instead of in your mind. You can cast them normally while you are within that node, even if you have left the node and returned since storing them there. Spellcasters who do not prepare spells: see COR_NODE_STORE_REST (dnd35CorSpellLists.ts, p. 26)."}'::jsonb),
('dnd35.cor.feat.cor-poison-immunity','General',1,'Poison Immunity','Poison Immunity','You are immune to one specific poison (chosen by you), whether available as a blade poison, the venom of a specific creature, or one other toxin. You also gain a +1 circumstance bonus on saving throws against other poisons.','—',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-poison-immunity","name":"Poison Immunity","type":"General","prerequisites":"—","benefit":"You are immune to one specific poison (chosen by you), whether available as a blade poison, the venom of a specific creature, or one other toxin. You also gain a +1 circumstance bonus on saving throws against other poisons.","special":"A character can take this feat multiple times, choosing a different poison each time. The +1 bonus against other poisons does not stack with itself."}'::jsonb),
('dnd35.cor.feat.cor-pulverize-foe','General',1,'Pulverize Foe','Pulverize Foe','If you hit the same enemy more than once in a single round with a bludgeoning melee weapon, you deal an extra 1d6 points of bludgeoning damage with each hit after the first.','Str 15, base attack bonus +6, proficient with bludgeoning melee weapon',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-pulverize-foe","name":"Pulverize Foe","type":"General","prerequisites":"Str 15, base attack bonus +6, proficient with bludgeoning melee weapon","benefit":"If you hit the same enemy more than once in a single round with a bludgeoning melee weapon, you deal an extra 1d6 points of bludgeoning damage with each hit after the first.","fighterBonus":true}'::jsonb),
('dnd35.cor.feat.cor-shadowform-familiar','General',1,'Shadowform Familiar','Shadowform Familiar','Your summoned familiar looks like a dark, shadowy version of a normal familiar. It is insubstantial and gains the incorporeal subtype (see Monster Manual page 310). A shadowform familiar is more closely bound to you than a normal familiar, and the maximum distance the shadowform familiar can travel is 30 feet per caster level. If you are separated from your shadowform familiar by a distance greater than this, the shadowform familiar dissolves into nothingness and is considered slain.','Krinth, summon familiar class feature',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-shadowform-familiar","name":"Shadowform Familiar","type":"General","prerequisites":"Krinth, summon familiar class feature","benefit":"Your summoned familiar looks like a dark, shadowy version of a normal familiar. It is insubstantial and gains the incorporeal subtype (see Monster Manual page 310). A shadowform familiar is more closely bound to you than a normal familiar, and the maximum distance the shadowform familiar can travel is 30 feet per caster level. If you are separated from your shadowform familiar by a distance greater than this, the shadowform familiar dissolves into nothingness and is considered slain.","special":"This feat does not transform a normal familiar into a shadowform familiar."}'::jsonb),
('dnd35.cor.feat.cor-shadowstrike','General',1,'Shadowstrike','Shadowstrike','When making an attack with a melee weapon in an area of shadowy illumination (see Player''s Handbook page 164), you gain a +1 circumstance bonus on the attack roll and deal an extra 1d6 points of damage.','Krinth, base attack bonus +1',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-shadowstrike","name":"Shadowstrike","type":"General","prerequisites":"Krinth, base attack bonus +1","benefit":"When making an attack with a melee weapon in an area of shadowy illumination (see Player''s Handbook page 164), you gain a +1 circumstance bonus on the attack roll and deal an extra 1d6 points of damage.","special":"A krinth fighter can select this feat as one of his fighter bonus feats.","fighterBonus":true}'::jsonb),
('dnd35.cor.feat.cor-skewer-foe','General',1,'Skewer Foe','Skewer Foe','If you hit the same enemy more than once in a single round with a piercing melee weapon, you deal an extra 1d6 points of piercing damage with each hit after the first.','Str 15, base attack bonus +6, proficient with piercing melee weapon',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-skewer-foe","name":"Skewer Foe","type":"General","prerequisites":"Str 15, base attack bonus +6, proficient with piercing melee weapon","benefit":"If you hit the same enemy more than once in a single round with a piercing melee weapon, you deal an extra 1d6 points of piercing damage with each hit after the first.","fighterBonus":true}'::jsonb),
('dnd35.cor.feat.cor-snatch-trophy','General',1,'Snatch Trophy','Snatch Trophy','After dealing a creature enough damage to drop it to negative hit points, you can slice or pry off a trophy as a free action. You must be adjacent to the dead or dying creature. The trophy could be a small body part such as a finger or ear. Carving a trophy in this manner requires a light slashing or piercing weapon and deals 1d6 points of damage to the target creature. (A creature with regeneration can regrow the severed body part.) Alternatively, you can take a small item worn or carried by your fallen foe, such as a piece of jewelry, pouch, potion, light weapon, or helmet, in which case the victim takes no damage. The snatched item can weigh no more than 2 pounds. You must have a free hand to collect the trophy.','—',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-snatch-trophy","name":"Snatch Trophy","type":"General","prerequisites":"—","benefit":"After dealing a creature enough damage to drop it to negative hit points, you can slice or pry off a trophy as a free action. You must be adjacent to the dead or dying creature. The trophy could be a small body part such as a finger or ear. Carving a trophy in this manner requires a light slashing or piercing weapon and deals 1d6 points of damage to the target creature. (A creature with regeneration can regrow the severed body part.) Alternatively, you can take a small item worn or carried by your fallen foe, such as a piece of jewelry, pouch, potion, light weapon, or helmet, in which case the victim takes no damage. The snatched item can weigh no more than 2 pounds. You must have a free hand to collect the trophy."}'::jsonb),
('dnd35.cor.feat.cor-touch-of-benevolence','General',1,'Touch of Benevolence','Touch of Benevolence','Although you are evil and spells such as detect evil reveal your true alignment, you have a 50% chance of ignoring any effect that specifically targets or damages evil creatures.','Any evil alignment',ARRAY['general']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-touch-of-benevolence","name":"Touch of Benevolence","type":"General","prerequisites":"Any evil alignment","benefit":"Although you are evil and spells such as detect evil reveal your true alignment, you have a 50% chance of ignoring any effect that specifically targets or damages evil creatures.","special":"To keep this feat, a character must demonstrate periodic acts of kindness and mercy. A DM can revoke this feat if the character fails to act in an appropriately conflicted manner."}'::jsonb),
('dnd35.cor.feat.cor-doomspeak','Bardic',1,'Doomspeak','Doomspeak','You can spend one of your bardic music uses to utter a string of crass and appalling epithets and curses at one enemy within 120 feet. The intended target must be able to hear and comprehend your damning remarks. A target that fails a Will save (DC 10 + your character level + your Cha modifier) is cursed with a -10 penalty on attack rolls, saves, ability checks, and skill checks for 1 round. This is a supernatural, necromantic effect.','Bardic music class feature, Intimidate 8 ranks, Perform 8 ranks',ARRAY['bardic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-doomspeak","name":"Doomspeak","type":"Bardic","prerequisites":"Bardic music class feature, Intimidate 8 ranks, Perform 8 ranks","benefit":"You can spend one of your bardic music uses to utter a string of crass and appalling epithets and curses at one enemy within 120 feet. The intended target must be able to hear and comprehend your damning remarks. A target that fails a Will save (DC 10 + your character level + your Cha modifier) is cursed with a -10 penalty on attack rolls, saves, ability checks, and skill checks for 1 round. This is a supernatural, necromantic effect."}'::jsonb),
('dnd35.cor.feat.cor-profane-outburst','Divine',1,'Profane Outburst','Profane Outburst','As a standard action, you can spend one of your rebuke attempts to bathe all undead creatures within 60 feet in divine energy, granting them a +1 profane bonus to Armor Class for 1 minute.','Ability to rebuke undead, evil alignment',ARRAY['divine']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-profane-outburst","name":"Profane Outburst","type":"Divine","prerequisites":"Ability to rebuke undead, evil alignment","benefit":"As a standard action, you can spend one of your rebuke attempts to bathe all undead creatures within 60 feet in divine energy, granting them a +1 profane bonus to Armor Class for 1 minute."}'::jsonb),
('dnd35.cor.feat.cor-via-negativa','Divine',1,'Via Negativa','Via Negativa','As a free action, you can spend one of your rebuke attempts to deal additional harm with an inflict spell. You must spend the rebuke attempt before making the attack roll. If the attack roll succeeds, the inflict spell deals an extra 1 point of damage per character level (maximum +20). If the attack roll fails, the rebuke attempt is spent and wasted.','Ability to rebuke undead',ARRAY['divine']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-via-negativa","name":"Via Negativa","type":"Divine","prerequisites":"Ability to rebuke undead","benefit":"As a free action, you can spend one of your rebuke attempts to deal additional harm with an inflict spell. You must spend the rebuke attempt before making the attack roll. If the attack roll succeeds, the inflict spell deals an extra 1 point of damage per character level (maximum +20). If the attack roll fails, the rebuke attempt is spent and wasted."}'::jsonb),
('dnd35.cor.feat.cor-corrupt-spell','Metamagic',1,'Corrupt Spell','Corrupt Spell','This feat adds the evil descriptor to one damaging spell you can cast. You must choose the spell at the time you select the feat. If the spell deals damage, half of the damage is unholy damage. For example, a corrupted fireball cast by a 6th-level wizard deals 6d6 points of damage: 3d6 points of fire damage and 3d6 points of unholy damage. Thus, creatures immune to fire still potentially take 3d6 points of damage.','Any evil alignment',ARRAY['metamagic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-corrupt-spell","name":"Corrupt Spell","type":"Metamagic","prerequisites":"Any evil alignment","benefit":"This feat adds the evil descriptor to one damaging spell you can cast. You must choose the spell at the time you select the feat. If the spell deals damage, half of the damage is unholy damage. For example, a corrupted fireball cast by a 6th-level wizard deals 6d6 points of damage: 3d6 points of fire damage and 3d6 points of unholy damage. Thus, creatures immune to fire still potentially take 3d6 points of damage.","special":"A character can take this feat multiple times, choosing a different spell each time. This feat originally appeared in Book of Vile Darkness and has been revised for D&D v.3.5."}'::jsonb),
('dnd35.cor.feat.cor-entangling-spell','Metamagic',1,'Entangling Spell','Entangling Spell','The feat can be applied to any instantaneous spell that deals acid, cold, electricity, fire, or sonic damage, such as fireball or lightning bolt. After the spell is cast, lingering tendrils of raw energy persist; creatures damaged by the spell are entangled for 1 round. The spell is considered to be in effect during this time and can be dispelled normally. An entangling spell uses up a spell slot two levels higher than the spell''s actual level.','—',ARRAY['metamagic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-entangling-spell","name":"Entangling Spell","type":"Metamagic","prerequisites":"—","benefit":"The feat can be applied to any instantaneous spell that deals acid, cold, electricity, fire, or sonic damage, such as fireball or lightning bolt. After the spell is cast, lingering tendrils of raw energy persist; creatures damaged by the spell are entangled for 1 round. The spell is considered to be in effect during this time and can be dispelled normally. An entangling spell uses up a spell slot two levels higher than the spell''s actual level."}'::jsonb),
('dnd35.cor.feat.cor-lingering-spell','Metamagic',1,'Lingering Spell','Lingering Spell','The feat can be applied to any instantaneous spell that deals acid, cold, electricity, fire, or sonic damage, such as fireball or lightning bolt. After the spell is cast, lingering tendrils of energy persist, dealing 1d6 points of damage of the appropriate energy type at the beginning of your next turn to all creatures initially damaged by the spell. The spell is considered to be in effect during this time and can be dispelled normally. A lingering spell uses up a spell slot one level higher than the spell''s actual level.','—',ARRAY['metamagic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-lingering-spell","name":"Lingering Spell","type":"Metamagic","prerequisites":"—","benefit":"The feat can be applied to any instantaneous spell that deals acid, cold, electricity, fire, or sonic damage, such as fireball or lightning bolt. After the spell is cast, lingering tendrils of energy persist, dealing 1d6 points of damage of the appropriate energy type at the beginning of your next turn to all creatures initially damaged by the spell. The spell is considered to be in effect during this time and can be dispelled normally. A lingering spell uses up a spell slot one level higher than the spell''s actual level."}'::jsonb),
('dnd35.cor.feat.cor-metanode-spell','Metamagic',1,'Metanode Spell','Metanode Spell','When casting a spell improved by a metamagic feat, you can deduct the class of the node layer in which you currently stand from the increased spell level. The class of the layer does not equal the class of the node unless you are standing in the innermost portion of it. For example, if you use Maximize Spell to augment the 5th-level spell flame strike in the innermost (+1) layer of a Class 1 node, you can cast the spell as if it were only two levels higher than normal, not three, because the node pays one spell level''s worth of the metamagic cost. This feat is most useful to casters who do not prepare spells (such as bards and sorcerers) and to wizards who rarely leave their nodes and can therefore prepare and cast their spells at the adjusted level. If you use this feat to reduce the cost of preparing a metamagic spell and then leave the node, the spell you prepared is unavailable until you return to a node layer of at least the same class as the one in which the spell was prepared.','Node Spellcasting, caster level 1st',ARRAY['metamagic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-metanode-spell","name":"Metanode Spell","type":"Metamagic","prerequisites":"Node Spellcasting, caster level 1st","benefit":"When casting a spell improved by a metamagic feat, you can deduct the class of the node layer in which you currently stand from the increased spell level. The class of the layer does not equal the class of the node unless you are standing in the innermost portion of it. For example, if you use Maximize Spell to augment the 5th-level spell flame strike in the innermost (+1) layer of a Class 1 node, you can cast the spell as if it were only two levels higher than normal, not three, because the node pays one spell level''s worth of the metamagic cost. This feat is most useful to casters who do not prepare spells (such as bards and sorcerers) and to wizards who rarely leave their nodes and can therefore prepare and cast their spells at the adjusted level. If you use this feat to reduce the cost of preparing a metamagic spell and then leave the node, the spell you prepared is unavailable until you return to a node layer of at least the same class as the one in which the spell was prepared."}'::jsonb),
('dnd35.cor.feat.cor-reaping-spell','Metamagic',1,'Reaping Spell','Reaping Spell','A raise dead, reincarnate, or resurrection spell cannot return to life a creature killed by a reaping spell, and a true resurrection spell has only a 50% chance of succeeding. A reaping spell that fails to kill the target has no additional effect. A reaping spell uses up a spell slot three levels higher than the spell''s actual level.','Any evil alignment',ARRAY['metamagic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-reaping-spell","name":"Reaping Spell","type":"Metamagic","prerequisites":"Any evil alignment","benefit":"A raise dead, reincarnate, or resurrection spell cannot return to life a creature killed by a reaping spell, and a true resurrection spell has only a 50% chance of succeeding. A reaping spell that fails to kill the target has no additional effect. A reaping spell uses up a spell slot three levels higher than the spell''s actual level."}'::jsonb),
('dnd35.cor.feat.cor-demonsworn-knight','Vile',1,'Demonsworn Knight','Demonsworn Knight','Any weapon you wield is treated as chaotic- and evil-aligned for the purpose of overcoming damage reduction. In addition, against lawful outsiders, you deal an extra 1d6 points of damage with any successful weapon attack.','Thrall to Demon, base attack bonus +4',ARRAY['vile']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-demonsworn-knight","name":"Demonsworn Knight","type":"Vile","prerequisites":"Thrall to Demon, base attack bonus +4","benefit":"Any weapon you wield is treated as chaotic- and evil-aligned for the purpose of overcoming damage reduction. In addition, against lawful outsiders, you deal an extra 1d6 points of damage with any successful weapon attack.","special":"This feat can only be taken once. A character who takes this feat cannot also take the Hellbound Knight or Tormented Knight feat. A fighter can select this feat as one of his fighter bonus feats. In addition, your eyes turn dead black, and your teeth become as sharp as fangs.","fighterBonus":true}'::jsonb),
('dnd35.cor.feat.cor-disciple-of-darkness','Vile',1,'Disciple of Darkness','Disciple of Darkness','Once per day, while performing an evil act, you can call upon your diabolic patron to add a +1 luck bonus to any one attack roll, saving throw, ability check, skill check, or level check.','Lawful evil alignment',ARRAY['vile']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-disciple-of-darkness","name":"Disciple of Darkness","type":"Vile","prerequisites":"Lawful evil alignment","benefit":"Once per day, while performing an evil act, you can call upon your diabolic patron to add a +1 luck bonus to any one attack roll, saving throw, ability check, skill check, or level check.","special":"This feat can only be taken once. A character who takes this feat cannot also take the Scion of Sorrow or Thrall to Demon feat."}'::jsonb),
('dnd35.cor.feat.cor-evil-brand','Vile',1,'Evil Brand','Evil Brand','Evil creatures automatically recognize the symbol now emblazoned upon you as a sign of your utter depravity or discipleship to a powerful patron, although the specific identity of the patron is not revealed. You gain a +2 circumstance bonus on Diplomacy and Intimidate checks made against evil creatures.','—',ARRAY['vile']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-evil-brand","name":"Evil Brand","type":"Vile","prerequisites":"—","benefit":"Evil creatures automatically recognize the symbol now emblazoned upon you as a sign of your utter depravity or discipleship to a powerful patron, although the specific identity of the patron is not revealed. You gain a +2 circumstance bonus on Diplomacy and Intimidate checks made against evil creatures."}'::jsonb),
('dnd35.cor.feat.cor-evil-embraced','Vile',1,'Evil Embraced','Evil Embraced','Once per day, as an immediate action (see page 21), you can call upon your fiendish patron to steel you against harm. You gain damage reduction 10/good for 1 round (until the start of your next turn).','Evil Brand',ARRAY['vile']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-evil-embraced","name":"Evil Embraced","type":"Vile","prerequisites":"Evil Brand","benefit":"Once per day, as an immediate action (see page 21), you can call upon your fiendish patron to steel you against harm. You gain damage reduction 10/good for 1 round (until the start of your next turn)."}'::jsonb),
('dnd35.cor.feat.cor-hellbound-knight','Vile',1,'Hellbound Knight','Hellbound Knight','Any weapon you wield is treated as lawful- and evil-aligned for the purpose of overcoming damage reduction. In addition, against chaotic outsiders, you gain a +1 profane bonus on attack rolls.','Disciple of Darkness, base attack bonus +4',ARRAY['vile']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-hellbound-knight","name":"Hellbound Knight","type":"Vile","prerequisites":"Disciple of Darkness, base attack bonus +4","benefit":"Any weapon you wield is treated as lawful- and evil-aligned for the purpose of overcoming damage reduction. In addition, against chaotic outsiders, you gain a +1 profane bonus on attack rolls.","special":"This feat can only be taken once. A character who takes this feat cannot also take the Demonsworn Knight or Tormented Knight feat. A fighter can select this feat as one of his fighter bonus feats. In addition, as soon as you take this feat, your eyes turn red.","fighterBonus":true}'::jsonb),
('dnd35.cor.feat.cor-scion-of-sorrow','Vile',1,'Scion of Sorrow','Scion of Sorrow','Once per day, while performing an evil act, you can call upon your fiendish patron to add a +1 luck bonus to any one attack roll, saving throw, ability check, skill check, or level check.','Neutral evil alignment',ARRAY['vile']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-scion-of-sorrow","name":"Scion of Sorrow","type":"Vile","prerequisites":"Neutral evil alignment","benefit":"Once per day, while performing an evil act, you can call upon your fiendish patron to add a +1 luck bonus to any one attack roll, saving throw, ability check, skill check, or level check.","special":"This feat can only be taken once. A character who takes this feat cannot also take the Disciple of Darkness or Thrall to Demon feat."}'::jsonb),
('dnd35.cor.feat.cor-thrall-to-demon','Vile',1,'Thrall to Demon','Thrall to Demon','Once per day, while performing an evil act, you can call upon your demonic patron to add a +1 luck bonus to any one attack roll, saving throw, ability check, skill check, or level check.','Chaotic evil alignment',ARRAY['vile']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-thrall-to-demon","name":"Thrall to Demon","type":"Vile","prerequisites":"Chaotic evil alignment","benefit":"Once per day, while performing an evil act, you can call upon your demonic patron to add a +1 luck bonus to any one attack roll, saving throw, ability check, skill check, or level check.","special":"This feat can only be taken once. A character who takes this feat cannot also take the Disciple of Darkness or Scion of Sorrow feat."}'::jsonb),
('dnd35.cor.feat.cor-tormented-knight','Vile',1,'Tormented Knight','Tormented Knight','Any weapon you wield is treated as evil-aligned for the purpose of overcoming damage reduction. Any chaotic or lawful outsider you successfully damage with a melee or ranged weapon must succeed on a Fortitude save (DC 10 + damage dealt) or take 1d4 points of Charisma damage.','Scion of Sorrow, base attack bonus +4',ARRAY['vile']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-tormented-knight","name":"Tormented Knight","type":"Vile","prerequisites":"Scion of Sorrow, base attack bonus +4","benefit":"Any weapon you wield is treated as evil-aligned for the purpose of overcoming damage reduction. Any chaotic or lawful outsider you successfully damage with a melee or ranged weapon must succeed on a Fortitude save (DC 10 + damage dealt) or take 1d4 points of Charisma damage.","special":"This feat can only be taken once. A character who takes this feat cannot also take the Demonsworn Knight or Hellbound Knight feat. A fighter can select this feat as one of his fighter bonus feats. In addition, as soon as you take this feat, your flesh turns pale and becomes unnaturally cold to the touch.","fighterBonus":true}'::jsonb),
('dnd35.cor.feat.cor-initiate-of-ghaunadaur','Initiate',1,'Initiate of Ghaunadaur','Initiate of Ghaunadaur','You can command or rebuke oozes as an evil cleric commands or rebukes undead. You can use this supernatural ability a number of times per day equal to 3 + your Cha modifier.','Cleric level 3rd, patron deity Ghaunadaur',ARRAY['initiate']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-initiate-of-ghaunadaur","name":"Initiate of Ghaunadaur","type":"Initiate","prerequisites":"Cleric level 3rd, patron deity Ghaunadaur","benefit":"You can command or rebuke oozes as an evil cleric commands or rebukes undead. You can use this supernatural ability a number of times per day equal to 3 + your Cha modifier.","addedSpells":[{"level":1,"name":"Corrosive Grasp"},{"level":2,"name":"Blindsight"},{"level":3,"name":"Amorphous Form"},{"level":5,"name":"Slime Hurl"},{"level":7,"name":"Mantle of the Slime Lord"}]}'::jsonb),
('dnd35.cor.feat.cor-initiate-of-gruumsh','Initiate',1,'Initiate of Gruumsh','Initiate of Gruumsh','Once per day, as a swift action, you can cast any cure spell you have prepared, or you can spontaneously cast an inflict spell.','Orc or half-orc, ability to cast 2nd-level divine spells, patron deity Gruumsh',ARRAY['initiate']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-initiate-of-gruumsh","name":"Initiate of Gruumsh","type":"Initiate","prerequisites":"Orc or half-orc, ability to cast 2nd-level divine spells, patron deity Gruumsh","benefit":"Once per day, as a swift action, you can cast any cure spell you have prepared, or you can spontaneously cast an inflict spell.","addedSpells":[{"level":2,"name":"Battle Line"},{"level":3,"name":"Bloodspear"},{"level":5,"name":"Pocket Cave"},{"level":6,"name":"Eyebite"},{"level":7,"name":"Waves of Exhaustion"}]}'::jsonb),
('dnd35.cor.feat.cor-initiate-of-kossuth','Initiate',1,'Initiate of Kossuth','Initiate of Kossuth','All fire elementals that you summon using the summon monster spells have +2 hit points per die (instead of average hit points).','Cleric level 3rd, patron deity Kossuth',ARRAY['initiate']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-initiate-of-kossuth","name":"Initiate of Kossuth","type":"Initiate","prerequisites":"Cleric level 3rd, patron deity Kossuth","benefit":"All fire elementals that you summon using the summon monster spells have +2 hit points per die (instead of average hit points).","addedSpells":[{"level":2,"name":"Agannazar''s Scorcher"},{"level":4,"name":"Fire Stride"},{"level":5,"name":"Shroud of Flame"},{"level":8,"name":"Incendiary Cloud"}]}'::jsonb),
('dnd35.cor.feat.cor-initiate-of-loviatar','Initiate',1,'Initiate of Loviatar','Initiate of Loviatar','The first time you take damage in any combat, you gain a +1 morale bonus on attack rolls and a +1 morale bonus on saving throws against fear effects for 1 minute per cleric level.','Cleric level 5th, patron deity Loviatar',ARRAY['initiate']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-initiate-of-loviatar","name":"Initiate of Loviatar","type":"Initiate","prerequisites":"Cleric level 5th, patron deity Loviatar","benefit":"The first time you take damage in any combat, you gain a +1 morale bonus on attack rolls and a +1 morale bonus on saving throws against fear effects for 1 minute per cleric level.","addedSpells":[{"level":2,"name":"Nybor''s Gentle Reminder"},{"level":3,"name":"Mystic Lash"},{"level":5,"name":"Fleshshiver"}]}'::jsonb),
('dnd35.cor.feat.cor-initiate-of-shar','Initiate',1,'Initiate of Shar','Initiate of Shar','You add Bluff and Hide to your list of class skills.','Able to cast 1st-level divine spells, patron deity Shar',ARRAY['initiate']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-initiate-of-shar","name":"Initiate of Shar","type":"Initiate","prerequisites":"Able to cast 1st-level divine spells, patron deity Shar","benefit":"You add Bluff and Hide to your list of class skills.","addedSpells":[{"level":1,"name":"Disguise Self"},{"level":3,"name":"Crushing Despair"},{"level":4,"name":"Armor of Darkness"},{"level":5,"name":"Darkbolt"}]}'::jsonb),
('dnd35.cor.feat.cor-initiate-of-varae','Initiate',1,'Initiate of Varae','Initiate of Varae','Once per day, as a standard action, you can transform your skin into shimmering emerald scales. The scales absorb magic missile damage as the shield spell, and they enable you to pass through walls of force as if they weren''t there. The emerald scales last for 1 minute per character level. This is a supernatural ability.','Extaminaar, cleric level 3rd, patron deity Varae',ARRAY['initiate']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',17,'dnd35','{"id":"cor-initiate-of-varae","name":"Initiate of Varae","type":"Initiate","prerequisites":"Extaminaar, cleric level 3rd, patron deity Varae","benefit":"Once per day, as a standard action, you can transform your skin into shimmering emerald scales. The scales absorb magic missile damage as the shield spell, and they enable you to pass through walls of force as if they weren''t there. The emerald scales last for 1 minute per character level. This is a supernatural ability.","addedSpells":[{"level":2,"name":"Blinding Spittle"},{"level":4,"name":"Serpent Arrow"},{"level":6,"name":"Veil"},{"level":8,"name":"Animal Shapes"}]}'::jsonb)
insert into public.catalog_spells (id,name_pt,name_en,description_pt,rank,is_cantrip,is_focus,traditions,cast_actions,range,targets,duration,defense,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cor.spell.cor-spell-air-breathing','Air Breathing','Air Breathing','The transmuted creatures can breathe air freely. Divide the duration evenly among all the creatures you touch. The spell does not make creatures unable to breathe water. Air breathing dispels and counters water breathing.',3,false,false,ARRAY['Cleric 3, druid 3, sorcerer/wizard 3']::text[],'1 standard action','Touch','Targets: Living creatures touched, up to one/level','2 hours/level; see text','Will negates (harmless)',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-air-breathing","name":"Air Breathing","school":"Transmutation","level":"Cleric 3, druid 3, sorcerer/wizard 3","components":"S, M/DF","castingTime":"1 standard action","range":"Touch","target":"Targets: Living creatures touched, up to one/level","duration":"2 hours/level; see text","savingThrow":"Will negates (harmless)","spellResistance":"Yes (harmless)","description":"The transmuted creatures can breathe air freely. Divide the duration evenly among all the creatures you touch. The spell does not make creatures unable to breathe water. Air breathing dispels and counters water breathing.","materialComponent":"A short reed or piece of straw (arcane)."}'::jsonb),
('dnd35.cor.spell.cor-spell-anathema','Anathema','Anathema','You can permanently break the divine link between your deity and a lower-level cleric, druid, ranger or paladin of your faith, or upon a common worshiper. The spell has no effect on spellcasters of a faith other than your own. You can pronounce an anathema upon any character of your faith, no matter where he is, even if on a different plane. You cannot pronounce an anathema against someone who is already dead. Some deities do not allow an anathema to be pronounced against the innocent or against their chosen, while others grant their high-level clerics free use of this most terrible of divine curses. An individual under anathema can no longer cast divine spells or call upon the power of his god to turn or command undead, heal, harm, smite, shape change, or use any other divine power associated with his character class. An ordinary worshiper placed under anathema is not allowed to take advantage of any of the faith''s services, such as healing, naming, marrying, or burial of the dead. Anyone who dies while under anathema is barred from entry into his deity''s plane just as though he had never declared allegiance to a god. His soul is condemned to eternally writhe in the Wall of the Faithless. On a more personal level, the anathema spell marks the subject as accursed with regard to others of the faith. They are not allowed to speak to him, look at him, or even acknowledge his existence. The common members of the faith are only aware that the subject is under anathema if so informed by the church hierarchy; however, clerics, paladins, druids and rangers of the faith can automatically detect an anathema effect simply by looking at the subject. The effect is permanent until lifted, either by the original spellcaster, or by a cleric of the same faith, of a higher level than the caster, who casts an atonement spell upon the subject. The subject of an anathema can also remove its effect by changing his divine allegiance (see Changing Deities, page 233 of the Forgotten Realms Campaign Setting).',9,false,false,ARRAY['Cleric 9, druid 9']::text[],'1 round','Unlimited','Target: One creature of the same faith as the spellcaster','Permanent','None',ARRAY['Enchantment (Compulsion)']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-anathema","name":"Anathema","school":"Enchantment (Compulsion)","level":"Cleric 9, druid 9","components":"V, S, F, DF","castingTime":"1 round","range":"Unlimited","target":"Target: One creature of the same faith as the spellcaster","duration":"Permanent","savingThrow":"None","spellResistance":"No","description":"You can permanently break the divine link between your deity and a lower-level cleric, druid, ranger or paladin of your faith, or upon a common worshiper. The spell has no effect on spellcasters of a faith other than your own. You can pronounce an anathema upon any character of your faith, no matter where he is, even if on a different plane. You cannot pronounce an anathema against someone who is already dead. Some deities do not allow an anathema to be pronounced against the innocent or against their chosen, while others grant their high-level clerics free use of this most terrible of divine curses. An individual under anathema can no longer cast divine spells or call upon the power of his god to turn or command undead, heal, harm, smite, shape change, or use any other divine power associated with his character class. An ordinary worshiper placed under anathema is not allowed to take advantage of any of the faith''s services, such as healing, naming, marrying, or burial of the dead. Anyone who dies while under anathema is barred from entry into his deity''s plane just as though he had never declared allegiance to a god. His soul is condemned to eternally writhe in the Wall of the Faithless. On a more personal level, the anathema spell marks the subject as accursed with regard to others of the faith. They are not allowed to speak to him, look at him, or even acknowledge his existence. The common members of the faith are only aware that the subject is under anathema if so informed by the church hierarchy; however, clerics, paladins, druids and rangers of the faith can automatically detect an anathema effect simply by looking at the subject. The effect is permanent until lifted, either by the original spellcaster, or by a cleric of the same faith, of a higher level than the caster, who casts an atonement spell upon the subject. The subject of an anathema can also remove its effect by changing his divine allegiance (see Changing Deities, page 233 of the Forgotten Realms Campaign Setting).","focus":"The subject''s name must be inscribed in a book or scroll especially consecrated for this purpose and detailing the crimes (real or imagined) for which the subject is being condemned. The book is not consumed in the process."}'::jsonb),
('dnd35.cor.spell.cor-spell-arrowsplit','Arrowsplit','Arrowsplit','This spell is cast upon a masterwork arrow or bolt, causing it to split in mid-flight into 1d4+1 identical masterwork arrows or bolts. All the missiles strike the same target, and you must make a separate attack roll for each missile. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.',3,false,false,ARRAY['Assassin 3, ranger 3, justice of weald and woe 3']::text[],'1 swift action','Touch','Target: One masterwork arrow or bolt','Instantaneous','None',ARRAY['Conjuration (Creation)']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-arrowsplit","name":"Arrowsplit","school":"Conjuration (Creation)","level":"Assassin 3, ranger 3, justice of weald and woe 3","components":"V, M","castingTime":"1 swift action","range":"Touch","target":"Target: One masterwork arrow or bolt","duration":"Instantaneous","savingThrow":"None","spellResistance":"Yes","description":"This spell is cast upon a masterwork arrow or bolt, causing it to split in mid-flight into 1d4+1 identical masterwork arrows or bolts. All the missiles strike the same target, and you must make a separate attack roll for each missile. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.","materialComponent":"Masterwork arrow or bolt."}'::jsonb),
('dnd35.cor.spell.cor-spell-battle-line','Battle Line','Battle Line','By means of this spell you draw a visible, unholy "line in the sand" that causes a feeling of dread and hesitation in all creatures that cross it. Any creature entering the affected area must make a Will save or become shaken. A creature that successfully saves cannot be affected again by the same spellcaster''s battle line spells for 24 hours.',2,false,false,ARRAY['Initiate of Gruumsh 2']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Area: Up to two contiguous 5-ft. squares/level, maximum 10 squares (S)','1 round/level','See text',ARRAY['Abjuration']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-battle-line","name":"Battle Line","school":"Abjuration","level":"Initiate of Gruumsh 2","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Area: Up to two contiguous 5-ft. squares/level, maximum 10 squares (S)","duration":"1 round/level","savingThrow":"See text","spellResistance":"See text","description":"By means of this spell you draw a visible, unholy \"line in the sand\" that causes a feeling of dread and hesitation in all creatures that cross it. Any creature entering the affected area must make a Will save or become shaken. A creature that successfully saves cannot be affected again by the same spellcaster''s battle line spells for 24 hours."}'::jsonb),
('dnd35.cor.spell.cor-spell-bedevil','Bedevil','Bedevil','You summon a mischievous spirit and send it to bedevil your enemy. The spirit seeks out its assigned victim wherever she might be, as long as she is on the same plane as you when you cast the spell. It then proceeds to irritate and annoy her through a variety of manifestations. The victim of a bedevil spell finds herself constantly seeing movement out of the corner of her eye. Her sleep is frequently interrupted by bed shaking and blanket shifting and the sounds of voices that fade upon waking. When spellcasting, she suffers a variety of minor irritations that threaten to disrupt her spells, and she constantly feels haunted and watched. The result of this bedevilment is that she takes a -1 penalty on all ability checks, skill checks, and Will saving throws and has a 5% chance of arcane spell failure (which stacks with any spell failure chance from armor worn). Detect evil cast upon the subject of this spell reveals the presence of the bedeviling spirit, while protection from evil keeps the spirit from adversely affecting the victim. A dispel evil spell destroys the mischievous spirit, but remove curse or similar magic has no effect on it.',3,false,false,ARRAY['Blackguard 3, sorcerer/wizard 3']::text[],'1 round','See text',null,'1 day/level (D)','No',ARRAY['Conjuration (Summoning) [Evil]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-bedevil","name":"Bedevil","school":"Conjuration (Summoning) [Evil]","level":"Blackguard 3, sorcerer/wizard 3","components":"V, S, M","castingTime":"1 round","range":"See text","duration":"1 day/level (D)","savingThrow":"No","spellResistance":"Yes","description":"You summon a mischievous spirit and send it to bedevil your enemy. The spirit seeks out its assigned victim wherever she might be, as long as she is on the same plane as you when you cast the spell. It then proceeds to irritate and annoy her through a variety of manifestations. The victim of a bedevil spell finds herself constantly seeing movement out of the corner of her eye. Her sleep is frequently interrupted by bed shaking and blanket shifting and the sounds of voices that fade upon waking. When spellcasting, she suffers a variety of minor irritations that threaten to disrupt her spells, and she constantly feels haunted and watched. The result of this bedevilment is that she takes a -1 penalty on all ability checks, skill checks, and Will saving throws and has a 5% chance of arcane spell failure (which stacks with any spell failure chance from armor worn). Detect evil cast upon the subject of this spell reveals the presence of the bedeviling spirit, while protection from evil keeps the spirit from adversely affecting the victim. A dispel evil spell destroys the mischievous spirit, but remove curse or similar magic has no effect on it.","materialComponent":"A tiny iron statuette of a devil or imp, plus either a drop of the intended victim''s blood or one personal article belonging to the intended victim."}'::jsonb),
('dnd35.cor.spell.cor-spell-bloodfreeze-arrow','Bloodfreeze Arrow','Bloodfreeze Arrow','This spell is cast upon a masterwork arrow or bolt, transforming its head into blue ice. In addition to taking normal damage from the missile, the target takes 2d6 points of cold damage and is paralyzed. A successful Fortitude save negates the paralysis, and the target can make a new save each round (at the start of the caster''s turn).',4,false,false,ARRAY['Assassin 4, ranger 4, justice of weald and woe 4']::text[],'1 swift action','Touch','Target: One masterwork arrow or bolt','Instantaneous','Fortitude partial; see text',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-bloodfreeze-arrow","name":"Bloodfreeze Arrow","school":"Transmutation","level":"Assassin 4, ranger 4, justice of weald and woe 4","components":"V, M","castingTime":"1 swift action","range":"Touch","target":"Target: One masterwork arrow or bolt","duration":"Instantaneous","savingThrow":"Fortitude partial; see text","spellResistance":"Yes","description":"This spell is cast upon a masterwork arrow or bolt, transforming its head into blue ice. In addition to taking normal damage from the missile, the target takes 2d6 points of cold damage and is paralyzed. A successful Fortitude save negates the paralysis, and the target can make a new save each round (at the start of the caster''s turn).","materialComponent":"Masterwork arrow or bolt."}'::jsonb),
('dnd35.cor.spell.cor-spell-bloodspear','Bloodspear','Bloodspear','This spell allows you to channel the fury of Gruumsh into the god''s favored weapon—a spear. The weapon''s tip begins to drip blood, and the spear acts as if it had the wounding special ability (see Dungeon Master''s Guide page 226) for the duration of the spell. The spell is automatically canceled 1 round after the weapon leaves your hand. You cannot have more than one bloodspear in effect at a time. This spell has no effect on a spear that already has the wounding special ability, and it does not work on artifacts.',3,false,false,ARRAY['Initiate of Gruumsh 3']::text[],'1 standard action','Touch','Target: Spear touched','1 round/level','None',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-bloodspear","name":"Bloodspear","school":"Transmutation","level":"Initiate of Gruumsh 3","components":"V, S","castingTime":"1 standard action","range":"Touch","target":"Target: Spear touched","duration":"1 round/level","savingThrow":"None","spellResistance":"No","description":"This spell allows you to channel the fury of Gruumsh into the god''s favored weapon—a spear. The weapon''s tip begins to drip blood, and the spear acts as if it had the wounding special ability (see Dungeon Master''s Guide page 226) for the duration of the spell. The spell is automatically canceled 1 round after the weapon leaves your hand. You cannot have more than one bloodspear in effect at a time. This spell has no effect on a spear that already has the wounding special ability, and it does not work on artifacts."}'::jsonb),
('dnd35.cor.spell.cor-spell-brilliant-energy-arrow','Brilliant Energy Arrow','Brilliant Energy Arrow','This spell is cast upon a masterwork arrow or bolt, transforming its head into brilliant energy that gives off light as a torch (20-foot radius). A brilliant energy missile ignores nonliving matter. Armor bonuses to AC (including any enhancement bonuses to that armor) do not count against it because the missile passes through armor. It deals normal damage and has no effect on constructs, undead, and objects. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.',2,false,false,ARRAY['Assassin 2, ranger 2, justice of weald and woe 2']::text[],'1 swift action','Touch','Target: One masterwork arrow or bolt','Instantaneous','None',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-brilliant-energy-arrow","name":"Brilliant Energy Arrow","school":"Transmutation","level":"Assassin 2, ranger 2, justice of weald and woe 2","components":"V, M","castingTime":"1 swift action","range":"Touch","target":"Target: One masterwork arrow or bolt","duration":"Instantaneous","savingThrow":"None","spellResistance":"Yes","description":"This spell is cast upon a masterwork arrow or bolt, transforming its head into brilliant energy that gives off light as a torch (20-foot radius). A brilliant energy missile ignores nonliving matter. Armor bonuses to AC (including any enhancement bonuses to that armor) do not count against it because the missile passes through armor. It deals normal damage and has no effect on constructs, undead, and objects. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.","materialComponent":"Masterwork arrow or bolt."}'::jsonb),
('dnd35.cor.spell.cor-spell-control-darkness-and-shadow','Control Darkness and Shadow','Control Darkness and Shadow','You can affect existing shadows, both natural and magical, by causing them to deepen, lighten, or even move. You can cause one of the following effects at a time, and can switch them once per round as a free action for the duration of the spell. The chosen effect covers the entire area of the spell; multiple effects may not be applied to different areas. The possible effects are described below. Deepen Darkness and Shadow: Normal shadows now grant a +4 bonus on Hide checks and provide concealment to creatures within them. Magical darkness now confers total concealment to anyone within its area. Lighten Darkness and Shadow: Normal shadows are suppressed within the area, making it impossible to hide within them or use abilities such as the shadowdancer''s shadow jump ability. Magical darkness no longer provides concealment, and the area can now be illuminated by any light source. Move Shadow: The affected shadow moves as you direct within the area. You can create shadow illusions (as those created by a silent image spell, but without color), reveal hidden creatures by taking their shadow away, cause shadows to follow you within the area of the spell, or otherwise move the shadow as you see fit. You cannot move areas of darkness in this way.',2,false,false,ARRAY['Bard 2, sorcerer/wizard 3']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Area: Shadows in one 5-ft. cube/level','Concentration + 1 round/level','None',ARRAY['Transmutation [Darkness, Shadow]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-control-darkness-and-shadow","name":"Control Darkness and Shadow","school":"Transmutation [Darkness, Shadow]","level":"Bard 2, sorcerer/wizard 3","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Area: Shadows in one 5-ft. cube/level","duration":"Concentration + 1 round/level","savingThrow":"None","spellResistance":"No","description":"You can affect existing shadows, both natural and magical, by causing them to deepen, lighten, or even move. You can cause one of the following effects at a time, and can switch them once per round as a free action for the duration of the spell. The chosen effect covers the entire area of the spell; multiple effects may not be applied to different areas. The possible effects are described below. Deepen Darkness and Shadow: Normal shadows now grant a +4 bonus on Hide checks and provide concealment to creatures within them. Magical darkness now confers total concealment to anyone within its area. Lighten Darkness and Shadow: Normal shadows are suppressed within the area, making it impossible to hide within them or use abilities such as the shadowdancer''s shadow jump ability. Magical darkness no longer provides concealment, and the area can now be illuminated by any light source. Move Shadow: The affected shadow moves as you direct within the area. You can create shadow illusions (as those created by a silent image spell, but without color), reveal hidden creatures by taking their shadow away, cause shadows to follow you within the area of the spell, or otherwise move the shadow as you see fit. You cannot move areas of darkness in this way."}'::jsonb),
('dnd35.cor.spell.cor-spell-darkflame-arrow','Darkflame Arrow','Darkflame Arrow','This spell is cast upon a masterwork arrow or bolt, engulfing its head in black fire. The arrow deals normal damage and wreathes the target in black flame that deals an extra 2d6 points of damage. The black flames continue to engulf the victim for 2 more rounds, dealing 2d6 points of damage each subsequent round (at the start of your turn), and they cannot be extinguished (although they can be dispelled). The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. Creatures with immunity or resistance to fire take full damage from the black flames. The projectile is destroyed even if it misses its target.',3,false,false,ARRAY['Assassin 3, justice of weald and woe 3, ranger 3']::text[],'1 swift action','Touch','Target: One masterwork arrow or bolt','Instantaneous; see text','None',ARRAY['Evocation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-darkflame-arrow","name":"Darkflame Arrow","school":"Evocation","level":"Assassin 3, justice of weald and woe 3, ranger 3","components":"V, M","castingTime":"1 swift action","range":"Touch","target":"Target: One masterwork arrow or bolt","duration":"Instantaneous; see text","savingThrow":"None","spellResistance":"Yes","description":"This spell is cast upon a masterwork arrow or bolt, engulfing its head in black fire. The arrow deals normal damage and wreathes the target in black flame that deals an extra 2d6 points of damage. The black flames continue to engulf the victim for 2 more rounds, dealing 2d6 points of damage each subsequent round (at the start of your turn), and they cannot be extinguished (although they can be dispelled). The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. Creatures with immunity or resistance to fire take full damage from the black flames. The projectile is destroyed even if it misses its target.","materialComponent":"Masterwork arrow or bolt."}'::jsonb),
('dnd35.cor.spell.cor-spell-doublestrike-arrow','Doublestrike Arrow','Doublestrike Arrow','This spell is cast upon a single arrow or crossbow bolt, enabling it to strike two targets instead of one. The character firing the arrow selects the two targets, both of which must be within 30 feet of each other, and makes a separate attack roll against each target (using the same attack bonus). After striking or missing the first target, the arrow swerves and continues on course to the second target. A doublestrike missile cannot hit the same target twice, and it is destroyed even if it misses its intended targets.',4,false,false,ARRAY['Ranger 4, justice of weald and woe 4']::text[],'1 swift action','Touch','Target: One arrow or bolt','1 round','None',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-doublestrike-arrow","name":"Doublestrike Arrow","school":"Transmutation","level":"Ranger 4, justice of weald and woe 4","components":"V, S, M","castingTime":"1 swift action","range":"Touch","target":"Target: One arrow or bolt","duration":"1 round","savingThrow":"None","spellResistance":"No","description":"This spell is cast upon a single arrow or crossbow bolt, enabling it to strike two targets instead of one. The character firing the arrow selects the two targets, both of which must be within 30 feet of each other, and makes a separate attack roll against each target (using the same attack bonus). After striking or missing the first target, the arrow swerves and continues on course to the second target. A doublestrike missile cannot hit the same target twice, and it is destroyed even if it misses its intended targets.","materialComponent":"Arrow or bolt."}'::jsonb),
('dnd35.cor.spell.cor-spell-enrage-animals','Enrage Animals','Enrage Animals','This spell incites and enrages animals, making them hostile and vicious. Only ordinary animals (those with Intelligence scores of 1 or 2) can be affected by this spell. The maximum number of Hit Dice of animals you can affect is equal to 2d4 + your caster level. A dire animal or an animal trained only to attack on order is allowed a saving throw; other animals are not. For example, a ranger could enrage a normal bear or wolf with little trouble, but it''s more difficult to drive a trained guard dog into a frenzy so that it attacks its master. The affected creatures attack the nearest creature, including any other creatures affected by this spell.',1,false,false,ARRAY['Druid 1, ranger 1']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Targets: Animals within 30 ft. of each other','1 minute/level','Will negates; see text',ARRAY['Enchantment (Compulsion) [Mind-Affecting]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-enrage-animals","name":"Enrage Animals","school":"Enchantment (Compulsion) [Mind-Affecting]","level":"Druid 1, ranger 1","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Targets: Animals within 30 ft. of each other","duration":"1 minute/level","savingThrow":"Will negates; see text","spellResistance":"Yes","description":"This spell incites and enrages animals, making them hostile and vicious. Only ordinary animals (those with Intelligence scores of 1 or 2) can be affected by this spell. The maximum number of Hit Dice of animals you can affect is equal to 2d4 + your caster level. A dire animal or an animal trained only to attack on order is allowed a saving throw; other animals are not. For example, a ranger could enrage a normal bear or wolf with little trouble, but it''s more difficult to drive a trained guard dog into a frenzy so that it attacks its master. The affected creatures attack the nearest creature, including any other creatures affected by this spell."}'::jsonb),
('dnd35.cor.spell.cor-spell-locate-node','Locate Node','Locate Node','You sense the direction of any node within range. You can choose to locate the nearest node, the closest node of a particular type, or a specific node you have visited before; in the latter case, the range is 2 miles/level and the area is a circle, centered on you, with a radius of 2 miles/level. The spell is blocked by even a thin sheet of lead, and it cannot detect nodes protected by a node lock spell.',2,false,false,ARRAY['Cleric 3, druid 2, sorcerer/wizard 2']::text[],'1 standard action','1 mile/level; see text','Area: Circle, centered on you, with a radius of 1 mile/level; see text','1 minute/level','None',ARRAY['Divination']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-locate-node","name":"Locate Node","school":"Divination","level":"Cleric 3, druid 2, sorcerer/wizard 2","components":"V, S, F/DF","castingTime":"1 standard action","range":"1 mile/level; see text","target":"Area: Circle, centered on you, with a radius of 1 mile/level; see text","duration":"1 minute/level","savingThrow":"None","spellResistance":"No","description":"You sense the direction of any node within range. You can choose to locate the nearest node, the closest node of a particular type, or a specific node you have visited before; in the latter case, the range is 2 miles/level and the area is a circle, centered on you, with a radius of 2 miles/level. The spell is blocked by even a thin sheet of lead, and it cannot detect nodes protected by a node lock spell.","focus":"A pebble found in a node (arcane or divine focus)."}'::jsonb),
('dnd35.cor.spell.cor-spell-love-s-lament','Love''s Lament','Love''s Lament','With this spell, you create a cone of music that draws upon the sadness, guilt, and despair of those within its area of effect. All creatures in the area take a -4 penalty on Listen checks for 1 round. In addition, those who fail to save against love''s lament are reminded of all their lost loves and disappointments in life. The music seizes upon these feelings and magnifies them, so that the victims of the spell take 1d6 points of Wisdom damage and are nauseated for 1d4 rounds.',3,false,false,ARRAY['Bard 3']::text[],'1 standard action','60 ft.','Effect: Cone-shaped burst','Instantaneous','Will negates',ARRAY['Enchantment (Compulsion) [Mind-Affecting]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-love-s-lament","name":"Love''s Lament","school":"Enchantment (Compulsion) [Mind-Affecting]","level":"Bard 3","components":"V","castingTime":"1 standard action","range":"60 ft.","target":"Effect: Cone-shaped burst","duration":"Instantaneous","savingThrow":"Will negates","spellResistance":"Yes","description":"With this spell, you create a cone of music that draws upon the sadness, guilt, and despair of those within its area of effect. All creatures in the area take a -4 penalty on Listen checks for 1 round. In addition, those who fail to save against love''s lament are reminded of all their lost loves and disappointments in life. The music seizes upon these feelings and magnifies them, so that the victims of the spell take 1d6 points of Wisdom damage and are nauseated for 1d4 rounds."}'::jsonb),
('dnd35.cor.spell.cor-spell-mantle-of-the-slime-lord','Mantle of the Slime Lord','Mantle of the Slime Lord','This spell causes a glossy nimbus of energy to surround you. This barrier looks like a gelatinous layer of thick, dirty water to observers, but it does not hinder you in the least. While the mantle is active, nonintelligent oozes will not attack you unless you attack them. In addition, you gain immunity to poison, sleep effects, paralysis, polymorph, and stunning effects. Lastly, when a critical hit or sneak attack is scored on you, there is a 75% chance that the critical hit or sneak attack is negated and damage is instead rolled normally.',7,false,false,ARRAY['Initiate of Ghaunadaur 7']::text[],'1 standard action','Personal','Effect: Nimbus of divine energy','10 minutes/level (D)','None',ARRAY['Abjuration']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-mantle-of-the-slime-lord","name":"Mantle of the Slime Lord","school":"Abjuration","level":"Initiate of Ghaunadaur 7","components":"V, S, DF","castingTime":"1 standard action","range":"Personal","target":"Effect: Nimbus of divine energy","duration":"10 minutes/level (D)","savingThrow":"None","spellResistance":"No","description":"This spell causes a glossy nimbus of energy to surround you. This barrier looks like a gelatinous layer of thick, dirty water to observers, but it does not hinder you in the least. While the mantle is active, nonintelligent oozes will not attack you unless you attack them. In addition, you gain immunity to poison, sleep effects, paralysis, polymorph, and stunning effects. Lastly, when a critical hit or sneak attack is scored on you, there is a 75% chance that the critical hit or sneak attack is negated and damage is instead rolled normally."}'::jsonb),
('dnd35.cor.spell.cor-spell-mark-of-the-unfaithful','Mark of the Unfaithful','Mark of the Unfaithful','You permanently place a mark upon a character or creature that identifies it as an enemy of the faith. Anyone of your faith who encounters the bearer of a mark of the unfaithful, even if he is disguised, altered, or polymorphed, feels a natural hostility toward that person and gains a +6 circumstance bonus on Sense Motive checks made against the marked creature. This hostility might not induce the viewer to attack, but he certainly will not be inclined to trust or believe anything the marked one says. Clerics, paladins, druids and rangers of the faith can automatically detect the mark simply by looking at the subject. A mark of the unfaithful is permanent until dispelled or removed by a cleric of the same faith, of higher level than the caster, who casts an atonement spell upon the subject.',7,false,false,ARRAY['Cleric 7, druid 7']::text[],'1 round','Unlimited','Target: One creature','Permanent','None',ARRAY['Evocation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-mark-of-the-unfaithful","name":"Mark of the Unfaithful","school":"Evocation","level":"Cleric 7, druid 7","components":"V, S, F","castingTime":"1 round","range":"Unlimited","target":"Target: One creature","duration":"Permanent","savingThrow":"None","spellResistance":"Yes","description":"You permanently place a mark upon a character or creature that identifies it as an enemy of the faith. Anyone of your faith who encounters the bearer of a mark of the unfaithful, even if he is disguised, altered, or polymorphed, feels a natural hostility toward that person and gains a +6 circumstance bonus on Sense Motive checks made against the marked creature. This hostility might not induce the viewer to attack, but he certainly will not be inclined to trust or believe anything the marked one says. Clerics, paladins, druids and rangers of the faith can automatically detect the mark simply by looking at the subject. A mark of the unfaithful is permanent until dispelled or removed by a cleric of the same faith, of higher level than the caster, who casts an atonement spell upon the subject.","focus":"The subject''s name must be inscribed in a book or scroll especially consecrated for this purpose and detailing the crimes (real or imagined) for which the subject is being marked."}'::jsonb),
('dnd35.cor.spell.cor-spell-necrotic-skull-bomb','Necrotic Skull Bomb','Necrotic Skull Bomb','You imbue a humanoid skull with negative energy and hurl it. The skull detonates on impact, releasing the negative energy contained within. All creatures in the spell''s area, except for undead, gain 1d4 negative levels (see Energy Drain, page 308 of the Monster Manual, for details about negative levels). Assuming a creature survives the effect of the spell, it regains lost levels after a number of hours equal to your caster level (maximum 15 hours). Usually, negative levels have a chance of draining a creature''s levels, but the negative levels from necrotic skull bomb don''t last long enough to do so. An undead creature in the spell''s area gains 1d4×5 temporary hit points for 1 hour.',5,false,false,ARRAY['Cleric 5, sorcerer/wizard 5']::text[],'1 swift action','Close (25 ft. + 5 ft./2 levels)','Area: 20-ft.-radius spread','Instantaneous','Fortitude negates',ARRAY['Necromancy']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-necrotic-skull-bomb","name":"Necrotic Skull Bomb","school":"Necromancy","level":"Cleric 5, sorcerer/wizard 5","components":"V, S, M","castingTime":"1 swift action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Area: 20-ft.-radius spread","duration":"Instantaneous","savingThrow":"Fortitude negates","spellResistance":"Yes","description":"You imbue a humanoid skull with negative energy and hurl it. The skull detonates on impact, releasing the negative energy contained within. All creatures in the spell''s area, except for undead, gain 1d4 negative levels (see Energy Drain, page 308 of the Monster Manual, for details about negative levels). Assuming a creature survives the effect of the spell, it regains lost levels after a number of hours equal to your caster level (maximum 15 hours). Usually, negative levels have a chance of draining a creature''s levels, but the negative levels from necrotic skull bomb don''t last long enough to do so. An undead creature in the spell''s area gains 1d4×5 temporary hit points for 1 hour.","materialComponent":"A humanoid skull."}'::jsonb),
('dnd35.cor.spell.cor-spell-node-door','Node Door','Node Door','You instantly transfer yourself from your current node to any other node of the same type that you have visited. You always arrive at the exact spot desired—whether by simply visualizing the area or by describing your destination (for example, "the Shadow Weave node in the garden at the Temple of Old Night"). After using this spell, you can''t take any other actions until your next turn. If you arrive in a node that is already partially occupied by a newly added object, you arrive in the closest clear space in that node. If the node is completely filled or has been destroyed by any means, you bounce to the next closest node of the same type (determined randomly or by the DM). Each such "bounce" deals 2d6 points of damage to you and any who accompany you. You can bring along objects as long as their weight doesn''t exceed your maximum load. You can also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels; a Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you. As with all spells for which the range is personal and the target is you, you need not make a saving throw, nor is spell resistance applicable to you. Only objects held or in use (attended) by another person receive saving throws and spell resistance. Special: You must have the Node Spellcasting feat to cast this spell.',3,false,false,ARRAY['Druid 3, sorcerer/wizard 3']::text[],'1 standard action','Varies; see text','Target: You and touched willing creatures','Instantaneous','None and Will negates (object)',ARRAY['Conjuration (Teleportation)']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-node-door","name":"Node Door","school":"Conjuration (Teleportation)","level":"Druid 3, sorcerer/wizard 3","components":"V","castingTime":"1 standard action","range":"Varies; see text","target":"Target: You and touched willing creatures","duration":"Instantaneous","savingThrow":"None and Will negates (object)","spellResistance":"No and Yes (object)","description":"You instantly transfer yourself from your current node to any other node of the same type that you have visited. You always arrive at the exact spot desired—whether by simply visualizing the area or by describing your destination (for example, \"the Shadow Weave node in the garden at the Temple of Old Night\"). After using this spell, you can''t take any other actions until your next turn. If you arrive in a node that is already partially occupied by a newly added object, you arrive in the closest clear space in that node. If the node is completely filled or has been destroyed by any means, you bounce to the next closest node of the same type (determined randomly or by the DM). Each such \"bounce\" deals 2d6 points of damage to you and any who accompany you. You can bring along objects as long as their weight doesn''t exceed your maximum load. You can also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels; a Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you. As with all spells for which the range is personal and the target is you, you need not make a saving throw, nor is spell resistance applicable to you. Only objects held or in use (attended) by another person receive saving throws and spell resistance. Special: You must have the Node Spellcasting feat to cast this spell."}'::jsonb),
('dnd35.cor.spell.cor-spell-node-genesis','Node Genesis','Node Genesis','When you cast this spell, the arcane energies reroute local ley lines and telluric currents, precipitating the creation of a Class 1 node (you determine the type when you cast the spell). The new node is centered on and emanates from a point on the ground you touch. The rough boundary of the new node can cross any type of terrain or empty space, and can cross different types of materials. You have some leeway in determining the initial shape of your node''s outer boundary—it doesn''t have to be a perfect sphere. The newly generated node retains its Class 1 status for one year. Thereafter, its diameter increases at rate of 20 feet per year, until it eventually reaches a diameter equal to 20 feet per the caster level you possessed at the time of casting. When the node''s diameter reaches the low end of the range for the next higher class (see Table 5-1 on page 96), its class increases by +1. For example, a Class 1 node becomes Class 2 when its diameter reaches 40 feet, and Class 3 when its diameter reaches 120 feet. Nodes you create with this spell are automatically considered node locked by you. They are otherwise just like natural nodes and subject to destruction in the same ways. Special: You must have the Node Spellcasting feat to cast this spell.',9,false,false,ARRAY['Sorcerer/wizard 9']::text[],'1 tenday (8 hours/day)','Touch','Effect: One Class 1 node with a 10-ft. radius','Instantaneous','None',ARRAY['Conjuration (Creation)']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-node-genesis","name":"Node Genesis","school":"Conjuration (Creation)","level":"Sorcerer/wizard 9","components":"V, S, XP","castingTime":"1 tenday (8 hours/day)","range":"Touch","target":"Effect: One Class 1 node with a 10-ft. radius","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","description":"When you cast this spell, the arcane energies reroute local ley lines and telluric currents, precipitating the creation of a Class 1 node (you determine the type when you cast the spell). The new node is centered on and emanates from a point on the ground you touch. The rough boundary of the new node can cross any type of terrain or empty space, and can cross different types of materials. You have some leeway in determining the initial shape of your node''s outer boundary—it doesn''t have to be a perfect sphere. The newly generated node retains its Class 1 status for one year. Thereafter, its diameter increases at rate of 20 feet per year, until it eventually reaches a diameter equal to 20 feet per the caster level you possessed at the time of casting. When the node''s diameter reaches the low end of the range for the next higher class (see Table 5-1 on page 96), its class increases by +1. For example, a Class 1 node becomes Class 2 when its diameter reaches 40 feet, and Class 3 when its diameter reaches 120 feet. Nodes you create with this spell are automatically considered node locked by you. They are otherwise just like natural nodes and subject to destruction in the same ways. Special: You must have the Node Spellcasting feat to cast this spell.","xpCost":"5,000 XP."}'::jsonb),
('dnd35.cor.spell.cor-spell-node-lock','Node Lock','Node Lock','A node lock spell cast upon a node magically "locks" it against others who might wish to use its power. You can affect a node whose class is equal to one-half your caster level or less. For any caster except you, a node lock adds +15 to each Spellcraft DC associated with the use of the node''s standard powers. In addition, the node cannot be detected by a locate node spell. A successful dispel magic breaks a node lock.',2,false,false,ARRAY['Sorcerer/wizard 2']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Target: One node','Permanent','None',ARRAY['Abjuration']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-node-lock","name":"Node Lock","school":"Abjuration","level":"Sorcerer/wizard 2","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Target: One node","duration":"Permanent","savingThrow":"None","spellResistance":"No","description":"A node lock spell cast upon a node magically \"locks\" it against others who might wish to use its power. You can affect a node whose class is equal to one-half your caster level or less. For any caster except you, a node lock adds +15 to each Spellcraft DC associated with the use of the node''s standard powers. In addition, the node cannot be detected by a locate node spell. A successful dispel magic breaks a node lock."}'::jsonb),
('dnd35.cor.spell.cor-spell-pocket-cave','Pocket Cave','Pocket Cave','You conjure up an extradimensional cave that has a single entrance on the plane from which the spell was cast. You can only cast this spell on a surface made of rock or some form of earth. The entry point looks like a dark cave entrance that is 4 feet wide and 8 feet high. Only those you designate can enter the cave, and the portal is shut and made invisible behind you when you enter. You can open it again from your side at will. Creatures entering the cave will find themselves in a dark, wet cavern. The place contains enough oxygen to sustain as many creatures as can fit in the area for the duration of the spell. Edible fungus grows along the walls, and condensation drips down one wall into a pool of fresh, clean water that never seems to run dry. External conditions such as weather do not affect the pleasant atmosphere of the cave, and nothing except the designated creatures can pass through the portal in either direction. At the end of the spell''s duration, all within the pocket cave return to the spot where they entered the cave or else to the nearest open space, if that spot is occupied.',5,false,false,ARRAY['Initiate of Gruumsh 5']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Effect: Extradimensional cave, up to two 10-ft. cubes/level (S)','1 hour/level (D)','None',ARRAY['Conjuration (Creation)']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-pocket-cave","name":"Pocket Cave","school":"Conjuration (Creation)","level":"Initiate of Gruumsh 5","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Effect: Extradimensional cave, up to two 10-ft. cubes/level (S)","duration":"1 hour/level (D)","savingThrow":"None","spellResistance":"No","description":"You conjure up an extradimensional cave that has a single entrance on the plane from which the spell was cast. You can only cast this spell on a surface made of rock or some form of earth. The entry point looks like a dark cave entrance that is 4 feet wide and 8 feet high. Only those you designate can enter the cave, and the portal is shut and made invisible behind you when you enter. You can open it again from your side at will. Creatures entering the cave will find themselves in a dark, wet cavern. The place contains enough oxygen to sustain as many creatures as can fit in the area for the duration of the spell. Edible fungus grows along the walls, and condensation drips down one wall into a pool of fresh, clean water that never seems to run dry. External conditions such as weather do not affect the pleasant atmosphere of the cave, and nothing except the designated creatures can pass through the portal in either direction. At the end of the spell''s duration, all within the pocket cave return to the spot where they entered the cave or else to the nearest open space, if that spot is occupied."}'::jsonb),
('dnd35.cor.spell.cor-spell-ravage','Ravage','Ravage','A terrible column of swirling black energy engulfs creatures and rips at their bodies and souls. All living creatures within the spell''s area take 1d6 points of vile damage per two caster levels (maximum 10d6). Unlike regular damage, vile damage can only be healed by magic cast within the area of a consecrate or hallow spell.',7,false,false,ARRAY['Cleric 7']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','Area: 10-ft.-radius cylinder, 40 ft. high','Instantaneous','Fortitude negates',ARRAY['Necromancy [Evil]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-ravage","name":"Ravage","school":"Necromancy [Evil]","level":"Cleric 7","components":"V, S, DF","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","target":"Area: 10-ft.-radius cylinder, 40 ft. high","duration":"Instantaneous","savingThrow":"Fortitude negates","spellResistance":"Yes","description":"A terrible column of swirling black energy engulfs creatures and rips at their bodies and souls. All living creatures within the spell''s area take 1d6 points of vile damage per two caster levels (maximum 10d6). Unlike regular damage, vile damage can only be healed by magic cast within the area of a consecrate or hallow spell."}'::jsonb),
('dnd35.cor.spell.cor-spell-remorseless-charm','Remorseless Charm','Remorseless Charm','This spell eliminates normal inhibitions and silences the subject''s conscience. Under its effects, a good creature might commit acts of extraordinary evil without any feelings of remorse. For instance, a paladin who strives to never destroy a foe that has surrendered might decide that she''s better off meting out justice immediately and killing the enemy. This spell affects the target''s norms and expectations; for example, once affected, a good-aligned target might be willing to attack his friends when urged to do so through a suggestion. This would not eliminate his need to atone, according to the tenets and punishments prescribed by his faith or law. The compulsion is permanent until broken by a break enchantment spell or similar magic, or until it is removed by the spellcaster.',5,false,false,ARRAY['Bard 5, cleric 6, sorcerer/wizard 6']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)',null,'See text','Will negates',ARRAY['Enchantment (Compulsion) [Evil, Mind-Affecting]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-remorseless-charm","name":"Remorseless Charm","school":"Enchantment (Compulsion) [Evil, Mind-Affecting]","level":"Bard 5, cleric 6, sorcerer/wizard 6","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","duration":"See text","savingThrow":"Will negates","spellResistance":"Yes","description":"This spell eliminates normal inhibitions and silences the subject''s conscience. Under its effects, a good creature might commit acts of extraordinary evil without any feelings of remorse. For instance, a paladin who strives to never destroy a foe that has surrendered might decide that she''s better off meting out justice immediately and killing the enemy. This spell affects the target''s norms and expectations; for example, once affected, a good-aligned target might be willing to attack his friends when urged to do so through a suggestion. This would not eliminate his need to atone, according to the tenets and punishments prescribed by his faith or law. The compulsion is permanent until broken by a break enchantment spell or similar magic, or until it is removed by the spellcaster.","materialComponent":"One piece of masterwork artwork of at least 1,000 gp in value. The artwork must depict acts of debauchery or evil that are titillating and fascinating, not disturbing. The spell is cast upon the artwork, which is then revealed to the subject of the spell, triggering its effects. The enchantment on the artwork lasts for 1 day per spellcaster level, much like a symbol, until it is viewed and its magical effect is triggered."}'::jsonb),
('dnd35.cor.spell.cor-spell-scourge-of-force','Scourge of Force','Scourge of Force','One or more whiplike tendrils of force spring from your hand and lash targets within range. Make a melee touch attack for each tendril using your highest attack bonus. If a tendril hits, it deals 1d8 points of force damage plus 1 point of force damage per two caster levels (maximum 1d8+5). You can lash a target with multiple tendrils.',2,false,false,ARRAY['Sorcerer/wizard 2']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Effect: One tendril of force plus one additional tendril per three caster levels (maximum four); Targets: One or more targets, no two of which can be more than 30 ft. apart','Instantaneous','None',ARRAY['Evocation [Force]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-scourge-of-force","name":"Scourge of Force","school":"Evocation [Force]","level":"Sorcerer/wizard 2","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Effect: One tendril of force plus one additional tendril per three caster levels (maximum four); Targets: One or more targets, no two of which can be more than 30 ft. apart","duration":"Instantaneous","savingThrow":"None","spellResistance":"Yes","description":"One or more whiplike tendrils of force spring from your hand and lash targets within range. Make a melee touch attack for each tendril using your highest attack bonus. If a tendril hits, it deals 1d8 points of force damage plus 1 point of force damage per two caster levels (maximum 1d8+5). You can lash a target with multiple tendrils."}'::jsonb),
('dnd35.cor.spell.cor-spell-serpent-arrow','Serpent Arrow','Serpent Arrow','You transform wooden arrows, darts, or twigs into Tiny vipers (see Monster Manual page 280). These missiles remain rigid and harmless until fired or hurled. They automatically bite any creature they hit, each dealing 1 point of damage plus poison (injury, Fortitude DC 11, initial and secondary damage 1d6 Con). The missiles remain in snake form for the duration of the spell, fighting the creatures they initially struck using their normal attack bonus. If a missile misses its target, or the target originally struck moves out of reach, the snake moves to attack the nearest creature other than you. If a target falls dead and no others are in range, the spell ends even if its duration has not run out. When the spell expires, the vipers melt away, leaving nothing behind.',3,false,false,ARRAY['Justice of weald and woe 3, sorcerer/wizard 4']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Target: Up to eight projectiles, all of which must be within 10 ft. of each other at the time of casting; see text','Up to 10 min./level; see text','None',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-serpent-arrow","name":"Serpent Arrow","school":"Transmutation","level":"Justice of weald and woe 3, sorcerer/wizard 4","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Target: Up to eight projectiles, all of which must be within 10 ft. of each other at the time of casting; see text","duration":"Up to 10 min./level; see text","savingThrow":"None","spellResistance":"No","description":"You transform wooden arrows, darts, or twigs into Tiny vipers (see Monster Manual page 280). These missiles remain rigid and harmless until fired or hurled. They automatically bite any creature they hit, each dealing 1 point of damage plus poison (injury, Fortitude DC 11, initial and secondary damage 1d6 Con). The missiles remain in snake form for the duration of the spell, fighting the creatures they initially struck using their normal attack bonus. If a missile misses its target, or the target originally struck moves out of reach, the snake moves to attack the nearest creature other than you. If a target falls dead and no others are in range, the spell ends even if its duration has not run out. When the spell expires, the vipers melt away, leaving nothing behind.","materialComponent":"Up to eight wooden arrows, darts, or straight twigs, plus a scale from any sort of snake."}'::jsonb),
('dnd35.cor.spell.cor-spell-shadow-arrow','Shadow Arrow','Shadow Arrow','This spell is cast upon a masterwork arrow or bolt, transforming it into pure black shadow. Make a ranged touch attack with the missile instead of a normal ranged attack. Instead of dealing normal damage, a shadow arrow deals 1d6 points of Strength damage. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.',4,false,false,ARRAY['Assassin 4, justice of weald and woe 4, ranger 4']::text[],'1 swift action','Touch','Target: One masterwork arrow or bolt','Instantaneous','None',ARRAY['Necromancy']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-shadow-arrow","name":"Shadow Arrow","school":"Necromancy","level":"Assassin 4, justice of weald and woe 4, ranger 4","components":"V, M","castingTime":"1 swift action","range":"Touch","target":"Target: One masterwork arrow or bolt","duration":"Instantaneous","savingThrow":"None","spellResistance":"Yes","description":"This spell is cast upon a masterwork arrow or bolt, transforming it into pure black shadow. Make a ranged touch attack with the missile instead of a normal ranged attack. Instead of dealing normal damage, a shadow arrow deals 1d6 points of Strength damage. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.","materialComponent":"Masterwork arrow or bolt."}'::jsonb),
('dnd35.cor.spell.cor-spell-shadow-trap','Shadow Trap','Shadow Trap','With this spell, you place a magic trap on any object that casts a shadow. If the object is disturbed in any way that causes its shadow to shift (for instance, if it or a nearby light source is moved), a bound greater shadow (see Monster Manual page 221) emerges from the object''s shadow to attack the nearest living creature. The shadow can be turned or destroyed as normal; otherwise, it remains for a number of rounds equal to your caster level. If the trapped object resides in a place that has no shadows, the trap does not trigger, although the spell remains in effect.',7,false,false,ARRAY['Cleric 7, sorcerer/wizard 7']::text[],'10 minutes','Touch',null,'1 hour/level (D)','Reflex half',ARRAY['Conjuration (Summoning) [Shadow]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-shadow-trap","name":"Shadow Trap","school":"Conjuration (Summoning) [Shadow]","level":"Cleric 7, sorcerer/wizard 7","components":"V, S, M","castingTime":"10 minutes","range":"Touch","duration":"1 hour/level (D)","savingThrow":"Reflex half","spellResistance":"Yes","description":"With this spell, you place a magic trap on any object that casts a shadow. If the object is disturbed in any way that causes its shadow to shift (for instance, if it or a nearby light source is moved), a bound greater shadow (see Monster Manual page 221) emerges from the object''s shadow to attack the nearest living creature. The shadow can be turned or destroyed as normal; otherwise, it remains for a number of rounds equal to your caster level. If the trapped object resides in a place that has no shadows, the trap does not trigger, although the spell remains in effect.","materialComponent":"A sheet of black cloth large enough to drape over the warded object."}'::jsonb),
('dnd35.cor.spell.cor-spell-slashing-darkness','Slashing Darkness','Slashing Darkness','A hissing, hurtling ribbon of pure darkness flies from your hand. A creature struck by this ray of darkness takes 1d8 points of damage per two caster levels (maximum 5d8). An undead creature instead heals 1d8 points of damage per two caster levels (maximum 5d8).',3,false,false,ARRAY['Clr 3']::text[],'1 standard action','Medium (100 ft. + 10 ft./level)','Effect: Ray','Instantaneous','None',ARRAY['Evocation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-slashing-darkness","name":"Slashing Darkness","school":"Evocation","level":"Clr 3","components":"V, S","castingTime":"1 standard action","range":"Medium (100 ft. + 10 ft./level)","target":"Effect: Ray","duration":"Instantaneous","savingThrow":"None","spellResistance":"Yes","description":"A hissing, hurtling ribbon of pure darkness flies from your hand. A creature struck by this ray of darkness takes 1d8 points of damage per two caster levels (maximum 5d8). An undead creature instead heals 1d8 points of damage per two caster levels (maximum 5d8)."}'::jsonb),
('dnd35.cor.spell.cor-spell-slime-hurl','Slime Hurl','Slime Hurl','You conjure and hurl three roughly spherical globs of dark green slime. You must succeed on a ranged touch attack to strike a target with a slime glob (roll separately for each glob, using your best ranged attack bonus). Any creature struck by a glob is coated in a patch of green slime (see Dungeon Master''s Guide page 76) and begins to experience its effects immediately. You can hit a creature with multiple globs, each of which must be dealt with separately. The conjured green slime does not disappear automatically and must be destroyed in the normal way.',5,false,false,ARRAY['Initiate of Ghaunadaur 5']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Effect: Three globs of green slime','Instantaneous','None',ARRAY['Conjuration (Creation)']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-slime-hurl","name":"Slime Hurl","school":"Conjuration (Creation)","level":"Initiate of Ghaunadaur 5","components":"V, S, DF","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Effect: Three globs of green slime","duration":"Instantaneous","savingThrow":"None","spellResistance":"No","description":"You conjure and hurl three roughly spherical globs of dark green slime. You must succeed on a ranged touch attack to strike a target with a slime glob (roll separately for each glob, using your best ranged attack bonus). Any creature struck by a glob is coated in a patch of green slime (see Dungeon Master''s Guide page 76) and begins to experience its effects immediately. You can hit a creature with multiple globs, each of which must be dealt with separately. The conjured green slime does not disappear automatically and must be destroyed in the normal way."}'::jsonb),
('dnd35.cor.spell.cor-spell-spellslayer-arrow','Spellslayer Arrow','Spellslayer Arrow','This spell is cast upon a masterwork arrow or bolt, transforming it into a glowing missile that destabilizes other forms of magic. In addition to dealing normal damage, a spellslayer arrow deals an extra 1d4 points of damage for each ongoing spell currently in effect on the target. For example, an arrow would deal an extra 3d4 points of damage to a creature under the effects of bull''s strength, haste, and mage armor. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.',2,false,false,ARRAY['Assassin 2, justice of weald and woe 2, ranger 2']::text[],'1 swift action','Touch','Target: One masterwork arrow or bolt','Instantaneous','None',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-spellslayer-arrow","name":"Spellslayer Arrow","school":"Transmutation","level":"Assassin 2, justice of weald and woe 2, ranger 2","components":"V, S, M","castingTime":"1 swift action","range":"Touch","target":"Target: One masterwork arrow or bolt","duration":"Instantaneous","savingThrow":"None","spellResistance":"Yes","description":"This spell is cast upon a masterwork arrow or bolt, transforming it into a glowing missile that destabilizes other forms of magic. In addition to dealing normal damage, a spellslayer arrow deals an extra 1d4 points of damage for each ongoing spell currently in effect on the target. For example, an arrow would deal an extra 3d4 points of damage to a creature under the effects of bull''s strength, haste, and mage armor. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.","materialComponent":"Masterwork arrow or bolt."}'::jsonb),
('dnd35.cor.spell.cor-spell-symphonic-nightmare','Symphonic Nightmare','Symphonic Nightmare','A creature targeted by this spell loses the ability to dream during sleep or rest. Rather, in place of dreams, the target''s slumbering mind is filled with the sounds of a discordant orchestra. After the victim''s first attempt to sleep, he incurs a -2 penalty on all Wisdom-based skill checks. This penalty persists as long as the symphonic nightmare effect maintains its hold on him. This spell affects all creatures that sleep or enter sleeplike trances; creatures without the need to sleep are effectively immune. In addition, the creature''s sleep is now haunted. It can no longer gain complete rest from sleeping or resting. The target does not regain hit points or heal ability damage naturally, nor is it able to prepare spells if doing so requires a full night''s rest. The creature is, however, now immune to the dream and nightmare spells, as well as to other effects that cause nightmares (such as the night hag''s dream haunting ability). The caster can lift the effect of this curse at will, but it is otherwise difficult to remove a symphonic nightmare before its duration expires. A remove curse cast at a higher caster level than the symphonic nightmare spell removes it, as does a successful break enchantment spell. Otherwise, a wish or miracle is required to lift the curse.',6,false,false,ARRAY['Bard 6']::text[],'1 standard action','Touch','Target: Living creature touched','1 day/level (D)','Will negates',ARRAY['Enchantment (Compulsion) [Mind-Affecting]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-symphonic-nightmare","name":"Symphonic Nightmare","school":"Enchantment (Compulsion) [Mind-Affecting]","level":"Bard 6","components":"V, S, F","castingTime":"1 standard action","range":"Touch","target":"Target: Living creature touched","duration":"1 day/level (D)","savingThrow":"Will negates","spellResistance":"Yes","description":"A creature targeted by this spell loses the ability to dream during sleep or rest. Rather, in place of dreams, the target''s slumbering mind is filled with the sounds of a discordant orchestra. After the victim''s first attempt to sleep, he incurs a -2 penalty on all Wisdom-based skill checks. This penalty persists as long as the symphonic nightmare effect maintains its hold on him. This spell affects all creatures that sleep or enter sleeplike trances; creatures without the need to sleep are effectively immune. In addition, the creature''s sleep is now haunted. It can no longer gain complete rest from sleeping or resting. The target does not regain hit points or heal ability damage naturally, nor is it able to prepare spells if doing so requires a full night''s rest. The creature is, however, now immune to the dream and nightmare spells, as well as to other effects that cause nightmares (such as the night hag''s dream haunting ability). The caster can lift the effect of this curse at will, but it is otherwise difficult to remove a symphonic nightmare before its duration expires. A remove curse cast at a higher caster level than the symphonic nightmare spell removes it, as does a successful break enchantment spell. Otherwise, a wish or miracle is required to lift the curse.","focus":"A small statue of an opened skull within which is arranged a miniature orchestra. The quality of this component must be extraordinary, giving it a value of at least 1,000 gp."}'::jsonb),
('dnd35.cor.spell.cor-spell-tvash-prull-s-bonefiddle','Tvash-Prull''s Bonefiddle','Tvash-Prull''s Bonefiddle','You call up a ghostly fiddle bow in the air above the targeted creature. This bow immediately descends into the subject''s body and begins to saw back and forth against its skeleton. Although the music produced is eerily beautiful, it causes intense pain and anguish to the victim. In each round of the duration, the victim takes 1d6 points of sonic damage and has a -20 penalty on all Move Silently checks; the sonic damage is considered to be continuous damage for the purposes of disrupting spellcasting. As a standard action, you can move the bonefiddle to another creature in range, but the new target gains a saving throw to resist the spell. If a target ever makes its saving throw, the bonefiddle vanishes and the spell ends. The spell''s effects continue even if the target moves so you no longer have line of sight or line of effect to it, but you cannot shift the bonefiddle to a new target unless you have both line of sight and line of effect to the current target and to the intended target.',2,false,false,ARRAY['Bard 2']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Target: One creature that has a skeleton or exoskeleton','Concentration, up to 1 round/level','Fortitude negates',ARRAY['Necromancy']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-tvash-prull-s-bonefiddle","name":"Tvash-Prull''s Bonefiddle","school":"Necromancy","level":"Bard 2","components":"V, S, M","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Target: One creature that has a skeleton or exoskeleton","duration":"Concentration, up to 1 round/level","savingThrow":"Fortitude negates","spellResistance":"Yes","description":"You call up a ghostly fiddle bow in the air above the targeted creature. This bow immediately descends into the subject''s body and begins to saw back and forth against its skeleton. Although the music produced is eerily beautiful, it causes intense pain and anguish to the victim. In each round of the duration, the victim takes 1d6 points of sonic damage and has a -20 penalty on all Move Silently checks; the sonic damage is considered to be continuous damage for the purposes of disrupting spellcasting. As a standard action, you can move the bonefiddle to another creature in range, but the new target gains a saving throw to resist the spell. If a target ever makes its saving throw, the bonefiddle vanishes and the spell ends. The spell''s effects continue even if the target moves so you no longer have line of sight or line of effect to it, but you cannot shift the bonefiddle to a new target unless you have both line of sight and line of effect to the current target and to the intended target.","materialComponent":"A miniature silver fiddle worth at least 30 gp."}'::jsonb),
('dnd35.cor.spell.cor-spell-undersong','Undersong','Undersong','When you cast this spell, a familiar and soothing song wells up in your mind. The song does not distract you from any task at hand—on the contrary, by humming along to the tune you can focus your mind with ease. As long as this spell is in effect, you can use any Perform check in place of a Concentration check. You must decide which skill to use before any check is made.',1,false,false,ARRAY['Bard 1']::text[],'1 standard action','Personal','Target: You','1 minute/level','None',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-undersong","name":"Undersong","school":"Transmutation","level":"Bard 1","components":"V","castingTime":"1 standard action","range":"Personal","target":"Target: You","duration":"1 minute/level","savingThrow":"None","spellResistance":"No","description":"When you cast this spell, a familiar and soothing song wells up in your mind. The song does not distract you from any task at hand—on the contrary, by humming along to the tune you can focus your mind with ease. As long as this spell is in effect, you can use any Perform check in place of a Concentration check. You must decide which skill to use before any check is made."}'::jsonb),
('dnd35.cor.spell.cor-spell-unholy-beast','Unholy Beast','Unholy Beast','When you cast this spell, the subject creature temporarily transforms into a being of evil, serving you for the duration of the spell. The animal''s limbs and face contort, it sprouts tusks and bone spurs through its skin, and its eyes turn completely black. The animal gains a +2 bonus to Strength, Dexterity, and Constitution, and a +2 bonus to natural armor. Furthermore, the damage of its natural attacks increases as if it were one size category larger. An unholy beast serves you as if it were under the influence of a dominate animal spell.',4,false,false,ARRAY['Druid 4']::text[],'1 standard action','Close (25 ft. + 5 ft./2 levels)','Target: One animal of up to 1 HD/level','1 round/level','Fortitude negates',ARRAY['Transmutation [Evil]']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-unholy-beast","name":"Unholy Beast","school":"Transmutation [Evil]","level":"Druid 4","components":"V, S","castingTime":"1 standard action","range":"Close (25 ft. + 5 ft./2 levels)","target":"Target: One animal of up to 1 HD/level","duration":"1 round/level","savingThrow":"Fortitude negates","spellResistance":"Yes","description":"When you cast this spell, the subject creature temporarily transforms into a being of evil, serving you for the duration of the spell. The animal''s limbs and face contort, it sprouts tusks and bone spurs through its skin, and its eyes turn completely black. The animal gains a +2 bonus to Strength, Dexterity, and Constitution, and a +2 bonus to natural armor. Furthermore, the damage of its natural attacks increases as if it were one size category larger. An unholy beast serves you as if it were under the influence of a dominate animal spell."}'::jsonb),
('dnd35.cor.spell.cor-spell-whip-of-thorns','Whip of Thorns','Whip of Thorns','When you cast this spell, a piece of vine grows into a thorn-studded whip capable of savagely ripping your opponent''s flesh. You can wield this whip as if you were proficient, and it follows all the rules for a whip except that it deals 1d8+1 points of lethal damage per strike. Any time you strike a Large or smaller opponent successfully with the whip, you can release it and entangle the creature. Doing this ends the spell, but the thorny vine continues to wrap around your enemy until the opponent breaks free with a successful Escape Artist check (DC equal to the save DC of the spell). On a failed check, the creature takes an additional 1d4 points of damage and remains entangled. On a successful check that exceeds the DC by 10 or less, the creature takes the additional damage in the process of freeing itself. A creature can also attempt to burst the vine with a DC 20 Strength check; it takes 1d4 points of damage whether or not the attempt succeeds.',2,false,false,ARRAY['Druid 2']::text[],'1 standard action','Personal','Effect: 15-foot-long whip covered with sharp thorns','1 round/level, or until discharged','None',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-whip-of-thorns","name":"Whip of Thorns","school":"Transmutation","level":"Druid 2","components":"V, S, M","castingTime":"1 standard action","range":"Personal","target":"Effect: 15-foot-long whip covered with sharp thorns","duration":"1 round/level, or until discharged","savingThrow":"None","spellResistance":"No","description":"When you cast this spell, a piece of vine grows into a thorn-studded whip capable of savagely ripping your opponent''s flesh. You can wield this whip as if you were proficient, and it follows all the rules for a whip except that it deals 1d8+1 points of lethal damage per strike. Any time you strike a Large or smaller opponent successfully with the whip, you can release it and entangle the creature. Doing this ends the spell, but the thorny vine continues to wrap around your enemy until the opponent breaks free with a successful Escape Artist check (DC equal to the save DC of the spell). On a failed check, the creature takes an additional 1d4 points of damage and remains entangled. On a successful check that exceeds the DC by 10 or less, the creature takes the additional damage in the process of freeing itself. A creature can also attempt to burst the vine with a DC 20 Strength check; it takes 1d4 points of damage whether or not the attempt succeeds.","materialComponent":"A tiny piece of vine."}'::jsonb),
('dnd35.cor.spell.cor-spell-woodwisp-arrow','Woodwisp Arrow','Woodwisp Arrow','This spell is cast upon a masterwork arrow or bolt, enabling the missile to pass through wood as though it was air, negating any cover benefit the target might enjoy because of wooden doors, tables, or stockade walls, or negating the AC modifier for a wooden shield. The spell doesn''t grant the spellcaster the ability to see through wooden obstructions, so unless a clairvoyance spell or similar magic is already in effect, the target is treated as having concealment instead of cover. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target.',1,false,false,ARRAY['Assassin 1, druid 1, justice of weald and woe 1, ranger 1']::text[],'1 swift action','Touch','Target: One masterwork arrow or bolt','1 min./level (D)','None',ARRAY['Transmutation']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',28,'dnd35','{"id":"cor-spell-woodwisp-arrow","name":"Woodwisp Arrow","school":"Transmutation","level":"Assassin 1, druid 1, justice of weald and woe 1, ranger 1","components":"V, S, M","castingTime":"1 swift action","range":"Touch","target":"Target: One masterwork arrow or bolt","duration":"1 min./level (D)","savingThrow":"None","spellResistance":"No","description":"This spell is cast upon a masterwork arrow or bolt, enabling the missile to pass through wood as though it was air, negating any cover benefit the target might enjoy because of wooden doors, tables, or stockade walls, or negating the AC modifier for a wooden shield. The spell doesn''t grant the spellcaster the ability to see through wooden obstructions, so unless a clairvoyance spell or similar magic is already in effect, the target is treated as having concealment instead of cover. The arrow or bolt must be fired during the same round the spell is cast, or the magic dissipates and is lost. The projectile is destroyed even if it misses its target."}'::jsonb),
('dnd35.cor.epic-spell.cor-epic-aumvors-fragmented-phylactery','Aumvor''s fragmented phylactery','Aumvor''s fragmented phylactery','This spell can only be cast by a lich. It either separates the lich''s phylactery into multiple objects or expands the phylactery to include multiple objects, as determined by the spellcaster. The number of such objects can be no greater than the caster''s modifier for its spellcasting ability (Charisma for a sorcerer, Intelligence for a wizard). Thereafter, destroying the lich''s phylactery requires the destruction of the whole set of objects that comprise the phylactery. As long as at least one such object of the set exists, the caster cannot be permanently killed. This spell can be cast repeatedly on a phylactery or part thereof. Each time it is cast, the number of objects that comprise the lich''s phylactery can be increased by an amount equal to the caster''s modifier for its spellcasting ability.',10,false,false,ARRAY['epic']::text[],'1 minute','Touch','One or more objects, including the caster''s phylactery','Permanent','None',ARRAY['Transmutation','epic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',37,'dnd35','{"id":"cor-epic-aumvors-fragmented-phylactery","name":"Aumvor''s fragmented phylactery","school":"Transmutation","spellcraftDC":30,"components":"V, S","castingTime":"1 minute","range":"Touch","target":"One or more objects, including the caster''s phylactery","duration":"Permanent","savingThrow":"None","spellResistance":"No","developmentGp":210000,"developmentDays":5,"developmentXp":8400,"seeds":[{"name":"transform","dc":21},{"name":"ward","dc":14}],"factors":"Mitigating factors: field specialization (-5).","description":"This spell can only be cast by a lich. It either separates the lich''s phylactery into multiple objects or expands the phylactery to include multiple objects, as determined by the spellcaster. The number of such objects can be no greater than the caster''s modifier for its spellcasting ability (Charisma for a sorcerer, Intelligence for a wizard). Thereafter, destroying the lich''s phylactery requires the destruction of the whole set of objects that comprise the phylactery. As long as at least one such object of the set exists, the caster cannot be permanently killed. This spell can be cast repeatedly on a phylactery or part thereof. Each time it is cast, the number of objects that comprise the lich''s phylactery can be increased by an amount equal to the caster''s modifier for its spellcasting ability."}'::jsonb),
('dnd35.cor.epic-spell.cor-epic-aumvors-soulshatter','Aumvor''s soulshatter','Aumvor''s soulshatter','For any one living creature within range, you separate soul from its body. The target is entitled to a DC 51 Fortitude save to survive the attack. If the save is successful, the creature instead takes 3d6+20 points of damage. If the save is failed, the subject''s soul is dead and passes on to the afterlife, but the body remains alive. After the successful casting of this spell, the body of the creature can then be possessed (as by a magic jar spell) or dominated (as by a dominate person spell) without resistance (automatic saving throw failure). The body retains the physical characteristics (Strength, Dexterity, Constitution, skills based on those abilities, and extraordinary abilities) of the departed soul but otherwise reflects the abilities and skills of the possessor or dominator. If not possessed or dominated, the body lies dormant—alive, but lacking an animating force. The soul can be returned to the body by means of a raise dead or resurrection spell at any time. The passage of time has no effect on the success of either spell, assuming the body is still alive.',10,false,false,ARRAY['epic']::text[],'1 minute','300 ft.','One living creature','Instantaneous','Fortitude partial',ARRAY['Necromancy','epic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',37,'dnd35','{"id":"cor-epic-aumvors-soulshatter","name":"Aumvor''s soulshatter","school":"Necromancy","spellcraftDC":51,"components":"V, S","castingTime":"1 minute","range":"300 ft.","target":"One living creature","duration":"Instantaneous","savingThrow":"Fortitude partial","spellResistance":"Yes","developmentGp":357000,"developmentDays":8,"developmentXp":14280,"seeds":[{"name":"slay","dc":25},{"name":"animate dead","dc":23}],"factors":"Factors: creating a ghost (+8). Mitigating factors: seed within specialist school (-5).","description":"For any one living creature within range, you separate soul from its body. The target is entitled to a DC 51 Fortitude save to survive the attack. If the save is successful, the creature instead takes 3d6+20 points of damage. If the save is failed, the subject''s soul is dead and passes on to the afterlife, but the body remains alive. After the successful casting of this spell, the body of the creature can then be possessed (as by a magic jar spell) or dominated (as by a dominate person spell) without resistance (automatic saving throw failure). The body retains the physical characteristics (Strength, Dexterity, Constitution, skills based on those abilities, and extraordinary abilities) of the departed soul but otherwise reflects the abilities and skills of the possessor or dominator. If not possessed or dominated, the body lies dormant—alive, but lacking an animating force. The soul can be returned to the body by means of a raise dead or resurrection spell at any time. The passage of time has no effect on the success of either spell, assuming the body is still alive."}'::jsonb),
('dnd35.cor.epic-spell.cor-epic-bonfire-of-insanity','Bonfire of insanity (ritual)','Bonfire of insanity (ritual)','A bonfire is built of human bones and burned during a rainstorm while this spell is cast. The smoke from the fire rises up and mingles with the rain clouds, filling them with vile power. As the tainted water rains down and soaks the ground, up to sixty corpses within range rise up as ghouls. Even skeletal remains are affected. The corpses receive no saving throw against the spell''s effects, not even if they are buried in consecrated ground. Humanoids (including the spellcasters) of up to 80 HD that are touched by the vile rain must make a Fortitude saving throw or be afflicted with a magical disease that turns them into flesh-starved ghouls within 24 hours. The disease is resistant to all forms of magical healing less powerful than a heal spell. The total Hit Dice worth of undead created from this spell, both from corpses and living creatures, is 180. The spell does not grant the spellcaster any ability to control the undead created by the spell. These undead can be commanded, rebuked, or turned normally.',10,false,false,ARRAY['epic']::text[],'10 minutes','1-mile radius',null,'Instantaneous','Fortitude negates; see text',ARRAY['Necromancy [Chaotic, Evil, Vile]','epic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',37,'dnd35','{"id":"cor-epic-bonfire-of-insanity","name":"Bonfire of insanity (ritual)","school":"Necromancy [Chaotic, Evil, Vile]","spellcraftDC":217,"components":"V, S, M","castingTime":"10 minutes","range":"1-mile radius","duration":"Instantaneous","savingThrow":"Fortitude negates; see text","spellResistance":"Yes","developmentGp":1953000,"developmentDays":39,"developmentXp":78120,"seeds":[{"name":"animate dead","dc":23},{"name":"slay","dc":25}],"factors":"Factors: area effect (+15) to 20-ft. radius (+2), increased 800% (+32), additional 160 HD (+160). Mitigating factors: increase casting time (-20), ghouls (-10), uncontrolled undead (-10).","description":"A bonfire is built of human bones and burned during a rainstorm while this spell is cast. The smoke from the fire rises up and mingles with the rain clouds, filling them with vile power. As the tainted water rains down and soaks the ground, up to sixty corpses within range rise up as ghouls. Even skeletal remains are affected. The corpses receive no saving throw against the spell''s effects, not even if they are buried in consecrated ground. Humanoids (including the spellcasters) of up to 80 HD that are touched by the vile rain must make a Fortitude saving throw or be afflicted with a magical disease that turns them into flesh-starved ghouls within 24 hours. The disease is resistant to all forms of magical healing less powerful than a heal spell. The total Hit Dice worth of undead created from this spell, both from corpses and living creatures, is 180. The spell does not grant the spellcaster any ability to control the undead created by the spell. These undead can be commanded, rebuked, or turned normally.","materialComponent":"A bonfire, at least 10 feet in diameter, made out of the remains of at least twenty humanoids. These remains are destroyed by the fire and are unaffected by the vile rain."}'::jsonb),
('dnd35.cor.epic-spell.cor-epic-cataract-of-fire','Cataract of fire','Cataract of fire','This spell is similar to the flame strike spell, in that a pillar of magical fire descends upon the target. The difference is the size and destructive power of the spell, and its magical source. A cataract of fire delivers 500 points of damage, equally divided between elemental fire and raw magical energy, to everything within a 300-foot radius centered on the spellcaster, 250 points of damage to everything outside the 300-foot radius but within a 600-foot radius, and 100 points of damage to everything else out to a quarter-mile. The pillar reaches well into the clouds and can be used to harm flying creatures. The nature of the spell grants the spellcaster immunity to the magical damage but not the fire damage. A successful Reflex saving throw halves the damage. The magical energy affects even magical matter, energy fields, and force effects that are normally only affected by a disintegrate spell, such as Bigby''s forceful hand, wall of force, globe of invulnerability, and antimagic field. Such effects are automatically destroyed.',10,false,false,ARRAY['epic']::text[],'1 minute','0 ft.','300-ft.-radius cylinder, 2,000 ft. tall; see text','Instantaneous','Reflex half',ARRAY['Evocation [Fire]','epic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',37,'dnd35','{"id":"cor-epic-cataract-of-fire","name":"Cataract of fire","school":"Evocation [Fire]","spellcraftDC":204,"components":"V, S, M","castingTime":"1 minute","range":"0 ft.","area":"300-ft.-radius cylinder, 2,000 ft. tall; see text","duration":"Instantaneous","savingThrow":"Reflex half","spellResistance":"Yes","developmentGp":1836000,"developmentDays":37,"developmentXp":73440,"seeds":[{"name":"energy","dc":19},{"name":"destroy","dc":29}],"factors":"Factors: increased damage die (+40), increased damage (+70), cylinder (+2), increase area (+18), maximized (+28). Mitigating factor: personal (-2).","description":"This spell is similar to the flame strike spell, in that a pillar of magical fire descends upon the target. The difference is the size and destructive power of the spell, and its magical source. A cataract of fire delivers 500 points of damage, equally divided between elemental fire and raw magical energy, to everything within a 300-foot radius centered on the spellcaster, 250 points of damage to everything outside the 300-foot radius but within a 600-foot radius, and 100 points of damage to everything else out to a quarter-mile. The pillar reaches well into the clouds and can be used to harm flying creatures. The nature of the spell grants the spellcaster immunity to the magical damage but not the fire damage. A successful Reflex saving throw halves the damage. The magical energy affects even magical matter, energy fields, and force effects that are normally only affected by a disintegrate spell, such as Bigby''s forceful hand, wall of force, globe of invulnerability, and antimagic field. Such effects are automatically destroyed.","materialComponent":"A bronze gong, which is struck when the spell is complete. The gong is consumed in the resulting conflagration."}'::jsonb),
('dnd35.cor.epic-spell.cor-epic-diluvial-torrent','Diluvial torrent','Diluvial torrent','This spell is similar to the cataract of fire spell, except that a cylinder of magical water drops upon the target area. A diluvial torrent delivers 500 points of damage, equally divided between physical damage and damage from raw magical energy, to everything within a 100-foot radius centered on the spellcaster, 250 points of damage to everything outside the 100-foot radius but within a 300-foot radius, and 100 points of damage to everything else out to 750 feet. The nature of the spell grants the spellcaster immunity to the magical damage but not the physical damage. A successful Reflex saving throw halves the damage. At the DM''s discretion, creatures surviving the initial impact of 628,000 cubic feet of water might also be subject to drowning and/or being swept away by the resulting flood.',10,false,false,ARRAY['epic']::text[],'1 minute','0 ft.','20-ft.-radius cylinder of water, 100 ft. tall, drops from a height of 200 ft.; see text','Instantaneous','Reflex half',ARRAY['Evocation [Water]','epic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',37,'dnd35','{"id":"cor-epic-diluvial-torrent","name":"Diluvial torrent","school":"Evocation [Water]","spellcraftDC":204,"components":"V, S, M","castingTime":"1 minute","range":"0 ft.","area":"20-ft.-radius cylinder of water, 100 ft. tall, drops from a height of 200 ft.; see text","duration":"Instantaneous","savingThrow":"Reflex half","spellResistance":"Yes","developmentGp":1836000,"developmentDays":37,"developmentXp":73440,"seeds":[{"name":"energy","dc":19},{"name":"destroy","dc":29}],"factors":"Factors: increased damage die (+40), increased damage (+70), cylinder (+2), increase area (+18), maximized (+28). Mitigating factor: personal (-2).","description":"This spell is similar to the cataract of fire spell, except that a cylinder of magical water drops upon the target area. A diluvial torrent delivers 500 points of damage, equally divided between physical damage and damage from raw magical energy, to everything within a 100-foot radius centered on the spellcaster, 250 points of damage to everything outside the 100-foot radius but within a 300-foot radius, and 100 points of damage to everything else out to 750 feet. The nature of the spell grants the spellcaster immunity to the magical damage but not the physical damage. A successful Reflex saving throw halves the damage. At the DM''s discretion, creatures surviving the initial impact of 628,000 cubic feet of water might also be subject to drowning and/or being swept away by the resulting flood.","materialComponent":"A silver gong, which is struck when the spell is complete. The gong is consumed in the resulting torrent."}'::jsonb),
('dnd35.cor.epic-spell.cor-epic-horrendous-dessication','Horrendous dessication','Horrendous dessication','This spell causes everything within the area to become desiccated—withering plants, mummifying flesh, drying up pools and ponds, and turning lush land to dust. Any living thing, not including the spellcaster, within the area takes 40 points of dessication damage per spellcaster level. The spell also absorbs 1,000 pounds (120 gallons) of water per caster level from any standing or moving body of water. Casting this spell permanently withers one of the spellcaster''s limbs.',10,false,false,ARRAY['epic']::text[],'1 minute','Personal','300-ft.-radius/level centered on the spellcaster','Instantaneous','Fortitude half',ARRAY['Necromancy','epic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',37,'dnd35','{"id":"cor-epic-horrendous-dessication","name":"Horrendous dessication","school":"Necromancy","spellcraftDC":118,"components":"V, S, M","castingTime":"1 minute","range":"Personal","area":"300-ft.-radius/level centered on the spellcaster","duration":"Instantaneous","savingThrow":"Fortitude half","spellResistance":"Yes","developmentGp":1062000,"developmentDays":22,"developmentXp":42480,"seeds":[{"name":"transport","dc":27}],"factors":"Factors: interplanar (+4), unwilling target (+4), area effect (+2), increase area (+16), area level dependent (+25), damage/volume level dependent (+25), augment minor magic item x10 (+40). Mitigating factor: loss of limb (-25).","description":"This spell causes everything within the area to become desiccated—withering plants, mummifying flesh, drying up pools and ponds, and turning lush land to dust. Any living thing, not including the spellcaster, within the area takes 40 points of dessication damage per spellcaster level. The spell also absorbs 1,000 pounds (120 gallons) of water per caster level from any standing or moving body of water. Casting this spell permanently withers one of the spellcaster''s limbs.","materialComponent":"One application of dust of dryness."}'::jsonb),
('dnd35.cor.epic-spell.cor-epic-necromantic-singularity','Necromantic singularity','Necromantic singularity','This powerful spell brings into being a short-lived conduit between the Material Plane, the magical Weave, and the Negative Energy Plane, allowing undiluted negative energy to spew into the world. The energy instantly slays up to 1,000 HD worth of living creatures. The spell kills creatures one at a time, in order of proximity to the singularity, until all 1,000 HD are accounted for.',10,false,false,ARRAY['epic']::text[],'1 minute','300 ft.','1-mile radius','Instantaneous','No',ARRAY['Necromancy [Death]','epic']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',37,'dnd35','{"id":"cor-epic-necromantic-singularity","name":"Necromantic singularity","school":"Necromancy [Death]","spellcraftDC":119,"components":"V, S, M","castingTime":"1 minute","range":"300 ft.","area":"1-mile radius","duration":"Instantaneous","savingThrow":"No","spellResistance":"Yes","developmentGp":1071000,"developmentDays":22,"developmentXp":42840,"seeds":[{"name":"slay","dc":25}],"factors":"Factors: increase HD (+96), target to area (+10), area radius (+2), increase area (+36). Mitigating factor: destroy minor artifact (-50).","description":"This powerful spell brings into being a short-lived conduit between the Material Plane, the magical Weave, and the Negative Energy Plane, allowing undiluted negative energy to spew into the world. The energy instantly slays up to 1,000 HD worth of living creatures. The spell kills creatures one at a time, in order of proximity to the singularity, until all 1,000 HD are accounted for.","materialComponent":"A sphere of annihilation. The sphere is destroyed by the spell."}'::jsonb)
insert into public.catalog_items (id,name_pt,name_en,description_pt,item_category,level,price_gp,traits,ruleset,source_book,source_page,system_id,data) values
('dnd35.cor.magic-item.cor-item-gnashing','Gnashing','Gnashing','When the wearer of a suit of gnashing armor is grappling, the carvings of faces animate and begin to bite, striving to tear at the opponent. The suit deals 1d6 points of damage to each grappling foe. The damage is considered piercing, slashing, and bludgeoning.','magic-item',0,null,ARRAY['armor ability']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-gnashing","name":"Gnashing","category":"armor ability","auraCasterLevel":"Strong transmutation; CL 11th","construction":"Craft Magic Arms and Armor, animate objects, variable gp, variable XP, variable days (depending on the armor being improved)","weight":"—","price":"+1 bonus","activation":"A suit of gnashing armor automatically bites any opponent that is grappling the wearer.","effect":"When the wearer of a suit of gnashing armor is grappling, the carvings of faces animate and begin to bite, striving to tear at the opponent. The suit deals 1d6 points of damage to each grappling foe. The damage is considered piercing, slashing, and bludgeoning."}'::jsonb),
('dnd35.cor.magic-item.cor-item-hideous','Hideous','Hideous','Hideous armor provides a +5 competence bonus on Intimidate checks and a -2 penalty on Diplomacy checks.','magic-item',0,null,ARRAY['armor ability']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-hideous","name":"Hideous","category":"armor ability","auraCasterLevel":"Faint conjuration; CL 4th","construction":"Craft Magic Arms and Armor, creator must have 5 ranks of Intimidate, +1,875 gp, +150 XP, +4 days (add to the cost of the armor being improved)","weight":"—","price":"+3,750 gp","activation":"Armor or a shield with the hideous special ability automatically grants its wearer its bonus.","effect":"Hideous armor provides a +5 competence bonus on Intimidate checks and a -2 penalty on Diplomacy checks.","variants":"Improved version: +10 competence bonus on Intimidate checks, costs +7,500 gp, +600 XP, +15 days, market price of +15,000 gp. Greater version: +15 competence bonus on Intimidate checks, costs +16,875 gp, +1,350 XP, +34 days, market price of +33,750 gp."}'::jsonb),
('dnd35.cor.magic-item.cor-item-ocular','Ocular','Ocular','This property grants the wearer all-around vision, making her exceptionally alert. The many eyes provide a +4 competence bonus on Spot and Search checks, and the wearer can''t be flanked. A blindness spell cast on the wearer negates this property.','magic-item',0,null,ARRAY['armor ability']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-ocular","name":"Ocular","category":"armor ability","auraCasterLevel":"Strong abjuration; CL 15th","construction":"Craft Magic Arms and Armor, arcane eye, variable gp, variable XP, variable days (depending on the armor being improved)","weight":"—","price":"+2 bonus","activation":"Armor or a shield with the ocular ability automatically grants its wearer its bonus.","effect":"This property grants the wearer all-around vision, making her exceptionally alert. The many eyes provide a +4 competence bonus on Spot and Search checks, and the wearer can''t be flanked. A blindness spell cast on the wearer negates this property."}'::jsonb),
('dnd35.cor.magic-item.cor-item-wary','Wary','Wary','This armor property increases your effective rogue level by four with regard to being flanked.','magic-item',0,null,ARRAY['armor ability']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-wary","name":"Wary","category":"armor ability","auraCasterLevel":"Faint transmutation; CL 5th","prerequisite":"Improved uncanny dodge ability","construction":"Craft Magic Arms and Armor, cat''s grace, +2,500 gp, +200 XP, +5 days (add to the cost of the armor being improved)","weight":"—","price":"+5,000 gp","activation":"Armor or a shield with the wary ability only functions if its wearer has improved uncanny dodge.","effect":"This armor property increases your effective rogue level by four with regard to being flanked."}'::jsonb),
('dnd35.cor.magic-item.cor-item-hellsteel','Hellsteel','Hellsteel','Hellsteel is a suit of +5 full plate that grants its wearer resistance to fire 5. Upon speaking a command word, the wearer can use a warm fire shield once per day. Any creature other than the wearer that touches the armor for a full round (such as by grappling or being grappled by the wearer) takes 2d6 points of fire damage per round as the metal sears its flesh.','magic-item',0,25650,ARRAY['specific armor']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-hellsteel","name":"Hellsteel","category":"specific armor","auraCasterLevel":"Moderate evocation; CL 10th","construction":"Craft Magic Arms and Armor, fire shield, resist elements, +12,825 gp, +1,026 XP, +12 days","weight":"50 lb.","price":"25,650 gp","activation":"Activating the armor''s fire shield ability is a free action. The fire shield ability functions only if the wearer is evil.","effect":"Hellsteel is a suit of +5 full plate that grants its wearer resistance to fire 5. Upon speaking a command word, the wearer can use a warm fire shield once per day. Any creature other than the wearer that touches the armor for a full round (such as by grappling or being grappled by the wearer) takes 2d6 points of fire damage per round as the metal sears its flesh."}'::jsonb),
('dnd35.cor.magic-item.cor-item-doomstrike','Doomstrike','Doomstrike','After successfully sundering an enemy''s weapon, the wielder of a doomstrike weapon can cleave into the enemy, as though using the Cleave feat.','magic-item',0,null,ARRAY['weapon ability']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-doomstrike","name":"Doomstrike","category":"weapon ability","auraCasterLevel":"Faint evocation; CL 5th","prerequisite":"Improved Sunder feat (wielder)","construction":"Cleave, Craft Magic Arms and Armor, shatter, +4,000 gp, +320 XP, +8 days","weight":"—","price":"+1 bonus","activation":"A melee weapon with the doomstrike ability only functions if its wielder has the Improved Sunder feat.","effect":"After successfully sundering an enemy''s weapon, the wielder of a doomstrike weapon can cleave into the enemy, as though using the Cleave feat."}'::jsonb),
('dnd35.cor.magic-item.cor-item-ravenous','Ravenous','Ravenous','When a ravenous weapon wounds a creature, it acquires a taste for that creature''s flesh and blood. Subsequent attacks made against the same creature during the same round deal an extra 2d6 points of damage (of the same type the weapon normally deals—bludgeoning, piercing, or slashing).','magic-item',0,null,ARRAY['weapon ability']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-ravenous","name":"Ravenous","category":"weapon ability","auraCasterLevel":"Moderate necromancy; CL 9th","construction":"Craft Magic Arms and Armor, slay living, creator must be evil, +9,000 gp, +720 XP, +18 days","weight":"—","price":"+2 bonus","activation":"A melee weapon with the ravenous ability only functions if its wielder is evil and can make multiple attacks in a single round.","effect":"When a ravenous weapon wounds a creature, it acquires a taste for that creature''s flesh and blood. Subsequent attacks made against the same creature during the same round deal an extra 2d6 points of damage (of the same type the weapon normally deals—bludgeoning, piercing, or slashing)."}'::jsonb),
('dnd35.cor.magic-item.cor-item-splitting','Splitting','Splitting','Any arrow or bolt fired from a splitting weapon magically splits into two missiles in mid-flight. Both missiles are identical, sharing the nonsplitting properties of the original missile. Both missiles strike the same target. Make a separate attack roll for each missile using the same attack bonus.','magic-item',0,null,ARRAY['weapon ability']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-splitting","name":"Splitting","category":"weapon ability","auraCasterLevel":"Moderate conjuration (creation); CL 7th","prerequisite":"Precise Shot feat (wielder)","construction":"Craft Magic Arms and Armor, Precise Shot, arrowsplit, +9,000 gp, +720 XP, +18 days","weight":"—","price":"+3 bonus","activation":"The splitting ability of a ranged weapon (must be a bow, crossbow, arrow, or bolt) only functions if its wielder has the Precise Shot feat.","effect":"Any arrow or bolt fired from a splitting weapon magically splits into two missiles in mid-flight. Both missiles are identical, sharing the nonsplitting properties of the original missile. Both missiles strike the same target. Make a separate attack roll for each missile using the same attack bonus."}'::jsonb),
('dnd35.cor.magic-item.cor-item-flensing-gauntlet','Flensing gauntlet','Flensing gauntlet','A flensing gauntlet is otherwise a +1 spiked gauntlet. A successful attack with an activated gauntlet tears a strip of flesh away from a living corporeal opponent. The opponent takes an extra 1d6 points of damage plus 1d4 points of Constitution damage and 1d4 points of Charisma damage. A Fortitude saving throw negates the ability damage and halves the extra hit point damage. Incorporeal creatures or creatures of a gaseous nature are not affected.','magic-item',0,17305,ARRAY['specific weapon']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-flensing-gauntlet","name":"Flensing gauntlet","category":"specific weapon","auraCasterLevel":"Strong evocation; CL 12th","construction":"Craft Magic Arms and Armor, flensing (see page 70 of the Forgotten Realms Campaign Setting), 8,805 gp, 680 XP, 17 days","weight":"1 lb.","price":"17,305 gp","activation":"As a move action, curl your gloved hand into a claw to activate the gauntlets. The effect lasts for 1 round. You can activate the gauntlets up to three times per day.","effect":"A flensing gauntlet is otherwise a +1 spiked gauntlet. A successful attack with an activated gauntlet tears a strip of flesh away from a living corporeal opponent. The opponent takes an extra 1d6 points of damage plus 1d4 points of Constitution damage and 1d4 points of Charisma damage. A Fortitude saving throw negates the ability damage and halves the extra hit point damage. Incorporeal creatures or creatures of a gaseous nature are not affected."}'::jsonb),
('dnd35.cor.magic-item.cor-item-camellia-of-the-black-lady','Camellia of the Black Lady','Camellia of the Black Lady','When the designated target comes within 20 feet of the wearer, he must make a DC 19 Will save (DC 21 if Selûne is his patron deity) or be captivated by a dominate person effect. In addition, he is subjected to a remorseless charm effect (no save) that stills his moral conscience. The subject remains in the thrall of the wearer for nine days, until the dominate person effect is dispelled, or until the camellia is destroyed. When the dominate person effect ends, Shar''s vengeance manifests as a poison spell, dealing 1d10 points of Constitution damage immediately and another 1d10 points 1 minute later (Fortitude DC 19, DC 21 if Selûne is the victim''s patron deity, negates each). A camellia can be used only once.','magic-item',0,7000,ARRAY['wondrous item']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-camellia-of-the-black-lady","name":"Camellia of the Black Lady","category":"wondrous item","auraCasterLevel":"Strong enchantment and necromancy; CL 13th","construction":"Craft Wondrous Item, dominate person, poison, remorseless charm*, 3,500 gp, 280 XP, 7 days (*new spell, page 34)","weight":"—","price":"7,000 gp","activation":"The wearer activates the blossom''s dominate person power by choosing a humanoid target and pressing the stem (a standard action). The poison effect activates automatically once the dominate person effect ends.","effect":"When the designated target comes within 20 feet of the wearer, he must make a DC 19 Will save (DC 21 if Selûne is his patron deity) or be captivated by a dominate person effect. In addition, he is subjected to a remorseless charm effect (no save) that stills his moral conscience. The subject remains in the thrall of the wearer for nine days, until the dominate person effect is dispelled, or until the camellia is destroyed. When the dominate person effect ends, Shar''s vengeance manifests as a poison spell, dealing 1d10 points of Constitution damage immediately and another 1d10 points 1 minute later (Fortitude DC 19, DC 21 if Selûne is the victim''s patron deity, negates each). A camellia can be used only once.","variants":"A used camellia of the Black Lady still retains its freshness, fragrance, and interesting appearance; it has a price of 200 gp."}'::jsonb),
('dnd35.cor.magic-item.cor-item-sanguine-nostrum','Sanguine nostrum','Sanguine nostrum','The powder is used to season the fresh heart of an enemy that has been dead for no more than 1 minute. If treated with sanguine nostrum and eaten immediately, the enemy''s heart grants you great insight, as through the effect of a moment of prescience spell. The more powerful the enemy, the greater the benefits; the caster level of the spell is equal to the Hit Dice of the creature whose heart you consumed with the powder. One vial of sanguine nostrum has one use.','magic-item',0,5000,ARRAY['wondrous item']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-sanguine-nostrum","name":"Sanguine nostrum","category":"wondrous item","auraCasterLevel":"Strong divination and necromancy; CL 15th","construction":"Craft Wondrous Item, moment of prescience, 2,500 gp, 20 XP, 5 days","weight":"—","price":"5,000 gp","activation":"The powder must be mixed with a recently killed enemy''s blood and sprinkled on its heart. Preparing and consuming the heart in this way takes 3 rounds.","effect":"The powder is used to season the fresh heart of an enemy that has been dead for no more than 1 minute. If treated with sanguine nostrum and eaten immediately, the enemy''s heart grants you great insight, as through the effect of a moment of prescience spell. The more powerful the enemy, the greater the benefits; the caster level of the spell is equal to the Hit Dice of the creature whose heart you consumed with the powder. One vial of sanguine nostrum has one use."}'::jsonb),
('dnd35.cor.magic-item.cor-item-gray-portrait','Gray portrait','Gray portrait','The owner of the gray portrait does not age or show signs of aging; as long as he owns the portrait, he will appear as young and as healthy as he did when he first acquired the artifact. When the owner of the portrait is subject to spells or effects that bestow negative levels or cause ability drain, such as an energy drain spell or a vampire''s touch, he does not suffer their effects. Instead, the portrait absorbs these debilitating effects. His image in the portrait transforms to look more haggard and depraved as it suffers the horrors that leave its owner untouched. The portrait stores and preserves all this horrible magic. If it is ever destroyed, the owner immediately suffers all the negative effects of age, negative levels, and ability drain that the portrait has absorbed. If the owner has outlived his natural life span, he instantly dies.','magic-item',0,null,ARRAY['major artifact']::text[],'v35-cor','D&D 3.5 — Champions of Ruin',40,'dnd35','{"id":"cor-item-gray-portrait","name":"Gray portrait","category":"major artifact","auraCasterLevel":"Overwhelming abjuration and necromancy; CL 20th","weight":"10 lb.","price":"—","activation":"After an individual possesses the portrait for one week, a picture of that individual owner appears on the canvas.","effect":"The owner of the gray portrait does not age or show signs of aging; as long as he owns the portrait, he will appear as young and as healthy as he did when he first acquired the artifact. When the owner of the portrait is subject to spells or effects that bestow negative levels or cause ability drain, such as an energy drain spell or a vampire''s touch, he does not suffer their effects. Instead, the portrait absorbs these debilitating effects. His image in the portrait transforms to look more haggard and depraved as it suffers the horrors that leave its owner untouched. The portrait stores and preserves all this horrible magic. If it is ever destroyed, the owner immediately suffers all the negative effects of age, negative levels, and ability drain that the portrait has absorbed. If the owner has outlived his natural life span, he instantly dies."}'::jsonb)
